head.b:skin:
/* ==========================================================================
   ANIME ARCHIVE - Blogger theme v2
   Complete encyclopedia redesign: cinematic homepage + editorial articles.
   Fraunces / IBM Plex Sans / IBM Plex Mono · #0F1117 base · #7C3AED accent
   Data source: Blogger posts, labels and feeds only. No external database.
   ========================================================================== */

:root {
  --bg: #0F1117;
  --bg-drawer: #111827;
  --card: #1A1D29;
  --card-edge: #2D3345;
  --ink: #F9FAFB;
  --ink-soft: #D1D5DB;
  --accent: #7C3AED;
  --accent-hover: #6D28D9;
  --accent-text: #A78BFA;
  --muted: #9CA3AF;
  --line: #3B4252;
  --font-display: "Fraunces", Georgia, "Times New Roman", serif;
  --font-body: "IBM Plex Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --header-h: 64px;
  --radius: 6px;
  --shadow: 0 8px 28px rgba(0,0,0,.45);
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body { margin: 0; padding: 0; background: var(--bg); color: var(--ink); font-family: var(--font-body), sans-serif; -webkit-font-smoothing: antialiased; line-height: 1.6; overflow-x: hidden; }
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
h1, h2, h3, h4 { margin: 0; }
[hidden] { display: none !important; }
:focus-visible { outline: 2px solid var(--accent-text); outline-offset: 2px; }
.section, .widget { margin: 0; padding: 0; }
#navbar-iframe-container, .blog-feeds, .post-feeds, .quickedit, .item-control { display: none !important; }
.aa-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.aa-skip { position: absolute; left: -999px; top: 6px; background: var(--accent); color: #fff; padding: .5rem .9rem; border-radius: 4px; z-index: 9999; }
.aa-skip:focus { left: 6px; }
.archive-frame { min-height: 100vh; display: flex; flex-direction: column; }

/* Reading progress */
.aa-progress { position: fixed; top: 0; left: 0; height: 3px; width: 0; background: var(--accent); z-index: 500; transition: width .1s linear; }

/* ---------- Sticky header + navigation ---------- */
.site-header {
  position: sticky; top: 0; z-index: 300;
  border-bottom: 1px solid var(--line);
  background: rgba(15,17,23,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.header-bar {
  max-width: 1200px; margin: 0 auto;
  display: flex; align-items: center; gap: 1rem;
  padding: 0 1.25rem; height: var(--header-h);
}
.brand { display: flex; align-items: center; gap: .6rem; flex-shrink: 0; }
.brand-title {
  font-family: var(--font-display), serif; font-weight: 900;
  font-size: 1.35rem; letter-spacing: -0.01em; line-height: 1;
  color: var(--ink);
}
.brand-title em { font-style: italic; font-weight: 400; color: var(--accent); }

/* Desktop nav */
.nav-desktop { display: none; flex: 1; align-items: center; gap: .15rem; margin-left: .5rem; }
.nav-item { position: relative; }
.nav-link {
  display: flex; align-items: center; gap: .25rem;
  padding: .45rem .7rem; border-radius: 4px;
  font-family: var(--font-mono), monospace; font-size: .72rem;
  letter-spacing: .03em; color: var(--muted); white-space: nowrap;
  transition: color .15s, background .15s;
}
.nav-link:hover, .nav-link:focus, .nav-item:hover > .nav-link, .nav-link.on {
  color: var(--ink); background: var(--card);
}
.nav-link .chev { font-size: .6rem; opacity: .7; transition: transform .2s; }
.nav-item:hover .chev, .nav-item:focus-within .chev { transform: rotate(180deg); }

/* Mega / dropdown panels */
.nav-panel {
  position: absolute; top: calc(100% + 6px); left: 0; min-width: 220px;
  background: var(--bg-drawer); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: .5rem 0; opacity: 0; visibility: hidden;
  transform: translateY(6px); transition: opacity .18s, transform .18s, visibility .18s; z-index: 40;
}
.nav-item:hover > .nav-panel, .nav-item:focus-within > .nav-panel {
  opacity: 1; visibility: visible; transform: translateY(0);
}
.nav-panel a {
  display: block; padding: .45rem 1rem;
  font-family: var(--font-mono), monospace; font-size: .74rem;
  color: var(--muted); letter-spacing: .02em;
}
.nav-panel a:hover, .nav-panel a:focus { color: var(--ink); background: var(--card); }
.nav-panel .panel-label {
  display: block; padding: .35rem 1rem .2rem;
  font-size: .62rem; color: var(--line); letter-spacing: .06em; text-transform: uppercase;
}

/* Header tools */
.header-tools { display: flex; align-items: center; gap: .5rem; margin-left: auto; }
.icon-btn {
  display: flex; align-items: center; justify-content: center;
  width: 38px; height: 38px; border-radius: 4px; border: 1px solid transparent;
  background: transparent; color: var(--muted); cursor: pointer;
  transition: color .15s, border-color .15s, background .15s;
}
.icon-btn:hover, .icon-btn:focus { color: var(--ink); border-color: var(--line); background: var(--card); }
.icon-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.menu-toggle { display: flex; }

/* Search overlay */
.search-overlay {
  position: fixed; inset: 0; z-index: 400;
  background: rgba(15,17,23,.88); backdrop-filter: blur(8px);
  display: flex; align-items: flex-start; justify-content: center;
  padding: 4rem 1rem 2rem; opacity: 0; visibility: hidden;
  transition: opacity .2s, visibility .2s;
}
.search-overlay.open { opacity: 1; visibility: visible; }
.search-panel {
  width: 100%; max-width: 640px; background: var(--bg-drawer);
  border: 1px solid var(--line); border-radius: 8px; box-shadow: var(--shadow);
  overflow: hidden;
}
.search-bar { display: flex; align-items: stretch; border-bottom: 1px solid var(--line); }
.search-type {
  background: transparent; border: 0; border-left: 1px solid var(--line);
  color: var(--muted); padding: 0 .9rem; font-family: var(--font-mono), monospace;
  font-size: .72rem; letter-spacing: .03em; cursor: pointer; outline: none;
}
.search-type:focus { color: var(--ink); }
.search-type-btn {
  display: flex; align-items: center; gap: .45rem; flex: none; background: transparent; border: 0;
  border-left: 1px solid var(--line); color: var(--muted); padding: 0 .9rem; cursor: pointer;
  font-family: var(--font-mono), monospace; font-size: .72rem; letter-spacing: .03em; white-space: nowrap;
}
.search-type-btn .chev { font-size: .6rem; opacity: .7; transition: transform .2s; }
.search-type-btn[aria-expanded="true"] { color: var(--ink); background: var(--card); }
.search-type-btn[aria-expanded="true"] .chev { transform: rotate(180deg); }
.search-type-btn:hover, .search-type-btn:focus-visible { color: var(--ink); }
.type-list {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: .4rem;
  padding: .7rem; border-bottom: 1px solid var(--line); max-height: 280px; overflow-y: auto;
}
.type-list[hidden] { display: none; }
.type-opt {
  text-align: left; background: transparent; border: 1px solid var(--line); border-radius: 4px;
  color: var(--muted); padding: .55rem .7rem; cursor: pointer;
  font-family: var(--font-mono), monospace; font-size: .74rem; letter-spacing: .02em;
}
.type-opt:hover, .type-opt:focus-visible { color: var(--ink); background: var(--card); }
.type-opt[aria-selected="true"] { color: var(--ink); background: var(--card); border-color: var(--accent); }
.search-input {
  flex: 1; min-width: 0; background: transparent; border: 0;
  color: var(--ink); padding: 1rem 1rem; font-family: var(--font-body), sans-serif;
  font-size: 1rem; outline: none;
}
.search-input::placeholder { color: var(--muted); }
.search-close {
  background: transparent; border: 0; color: var(--muted); padding: 0 1rem;
  cursor: pointer; font-size: 1.2rem; line-height: 1;
}
.search-close:hover { color: var(--ink); }
.search-suggest { max-height: 360px; overflow-y: auto; }
.suggest-item {
  display: flex; align-items: center; gap: .75rem; padding: .65rem 1rem;
  border-bottom: 1px solid var(--line); font-size: .9rem; transition: background .12s;
}
.suggest-item:last-child { border-bottom: 0; }
.suggest-item:hover, .suggest-item:focus { background: var(--card); }
.suggest-item img, .suggest-item .art-ph {
  width: 40px; height: 60px; object-fit: cover; border-radius: 3px; flex: none; background: var(--card-edge);
}
.suggest-meta { font-family: var(--font-mono), monospace; font-size: .68rem; color: var(--muted); margin-top: .15rem; }
.search-empty, .search-loading {
  padding: 1.5rem; text-align: center; color: var(--muted);
  font-family: var(--font-mono), monospace; font-size: .8rem;
}

/* Mobile drawer */
.drawer-backdrop {
  position: fixed; inset: 0; background: rgba(0,0,0,.55); z-index: 350;
  opacity: 0; visibility: hidden; transition: opacity .25s, visibility .25s;
}
.drawer-backdrop.open { opacity: 1; visibility: visible; }
.drawer {
  position: fixed; top: 0; left: 0; bottom: 0; width: min(320px, 88vw);
  background: var(--bg-drawer); border-right: 1px solid var(--line);
  z-index: 360; transform: translateX(-100%); transition: transform .28s ease;
  display: flex; flex-direction: column; overflow: hidden;
}
.drawer.open { transform: translateX(0); }
.drawer-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 1rem 1.1rem; border-bottom: 1px solid var(--line);
}
.drawer-brand { font-family: var(--font-display), serif; font-weight: 900; font-size: 1.15rem; }
.drawer-brand em { font-style: italic; font-weight: 400; color: var(--accent); }
.drawer-close {
  width: 36px; height: 36px; display: flex; align-items: center; justify-content: center;
  background: transparent; border: 1px solid var(--line); border-radius: 4px;
  color: var(--muted); cursor: pointer; font-size: 1.1rem;
}
.drawer-close:hover { color: var(--ink); border-color: var(--accent); }
.drawer-nav { flex: 1; overflow-y: auto; padding: .75rem 0; }
.drawer-section { margin-bottom: .5rem; }
.drawer-section-title {
  display: block; padding: .5rem 1.1rem .25rem;
  font-family: var(--font-mono), monospace; font-size: .62rem;
  letter-spacing: .06em; color: var(--line); text-transform: uppercase;
}
.drawer-link {
  display: block; padding: .55rem 1.1rem;
  font-family: var(--font-mono), monospace; font-size: .8rem;
  color: var(--muted); letter-spacing: .02em;
}
.drawer-link:hover, .drawer-link:focus, .drawer-link.on { color: var(--ink); background: var(--card); }
.drawer-sub { padding-left: .75rem; }

/* ---------- Hero (homepage) ---------- */
.hero {
  position: relative; max-width: 1200px; margin: 0 auto;
  padding: 1.5rem 1.25rem 0;
}
.hero-card {
  position: relative; border-radius: 10px; overflow: hidden;
  background: var(--card); min-height: 320px;
  display: grid; grid-template-columns: 1fr;
}
.hero-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, #1a1230 0%, #0F1117 50%, #141827 100%);
}
.hero-bg img {
  width: 100%; height: 100%; object-fit: cover; opacity: .45;
}
.hero-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to right, rgba(15,17,23,.92) 0%, rgba(15,17,23,.7) 45%, rgba(15,17,23,.25) 100%),
              linear-gradient(to top, rgba(15,17,23,.9) 0%, transparent 50%);
}
.hero-content {
  position: relative; z-index: 2; padding: 2rem 1.5rem;
  display: flex; flex-direction: column; justify-content: flex-end; gap: .75rem;
  max-width: 560px;
}
.hero-stamps { display: flex; flex-wrap: wrap; gap: .4rem; }
.hero-title {
  font-family: var(--font-display), serif; font-weight: 900;
  font-size: clamp(1.7rem, 4.5vw, 2.6rem); line-height: 1.15; color: var(--ink);
}
.hero-desc {
  font-size: .95rem; color: var(--ink-soft); line-height: 1.55;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: .4rem; }
.btn-primary {
  display: inline-flex; align-items: center; gap: .4rem;
  background: var(--accent); color: #fff; padding: .65rem 1.2rem;
  border-radius: 4px; font-family: var(--font-mono), monospace; font-size: .78rem;
  letter-spacing: .03em; border: 0; cursor: pointer; transition: background .15s;
}
.btn-primary:hover { background: var(--accent-hover); color: #fff; }
.btn-ghost {
  display: inline-flex; align-items: center; gap: .4rem;
  background: transparent; color: var(--ink-soft); padding: .65rem 1.1rem;
  border-radius: 4px; font-family: var(--font-mono), monospace; font-size: .78rem;
  letter-spacing: .03em; border: 1px solid var(--line); cursor: pointer;
  transition: border-color .15s, color .15s;
}
.btn-ghost:hover { border-color: var(--accent); color: var(--ink); }
.hero-nav {
  position: absolute; bottom: 1.25rem; right: 1.25rem; z-index: 3;
  display: flex; gap: .4rem;
}
.hero-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--line);
  border: 0; cursor: pointer; padding: 0; transition: background .15s;
}
.hero-dot.on, .hero-dot:hover { background: var(--accent); }
.hero-skel { min-height: 320px; border-radius: 10px; background: var(--card); }

/* ---------- Category grid ---------- */
.cat-grid-section { max-width: 1200px; margin: 0 auto; padding: 2rem 1.25rem 0; }
.cat-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: .75rem; margin-top: 1rem;
}
.cat-card {
  display: flex; flex-direction: column; align-items: flex-start; justify-content: flex-end;
  aspect-ratio: 16 / 10; border-radius: var(--radius); padding: 1rem;
  background: var(--card); border: 1px solid var(--line);
  position: relative; overflow: hidden; transition: border-color .15s, transform .15s;
}
.cat-card:hover { border-color: var(--accent); transform: translateY(-2px); }
.cat-card::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(145deg, rgba(124,58,237,.12), transparent 60%);
  pointer-events: none;
}
.cat-card span {
  position: relative; font-family: var(--font-display), serif; font-weight: 600;
  font-size: 1.05rem; color: var(--ink);
}
.cat-card small {
  position: relative; font-family: var(--font-mono), monospace; font-size: .68rem;
  color: var(--muted); margin-top: .2rem;
}

/* ---------- Sections and rows ---------- */
.page-wrap { max-width: 1200px; margin: 0 auto; }
.section-head {
  max-width: 1200px; margin: 2.25rem auto 0; padding: 0 1.25rem;
  display: flex; align-items: baseline; justify-content: space-between; gap: 1rem;
}
.section-title {
  font-family: var(--font-display), serif; font-weight: 600; font-size: 1.4rem; color: var(--ink);
}
h1.section-title { font-size: 1.85rem; font-weight: 900; }
.section-sub {
  max-width: 1200px; margin: .3rem auto 0; padding: 0 1.25rem;
  font-family: var(--font-mono), monospace; font-size: .75rem; color: var(--muted); letter-spacing: .03em;
}
.view-all {
  font-family: var(--font-mono), monospace; font-size: .72rem; color: var(--accent-text);
  letter-spacing: .03em; white-space: nowrap;
}
.view-all:hover { color: #fff; }

.archive-scroll {
  max-width: 1200px; margin: 0 auto; padding: 1.1rem 1rem;
  display: flex; flex-wrap: nowrap; overflow-x: auto; overflow-y: hidden;
  gap: .65rem; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
  scrollbar-width: none; -ms-overflow-style: none;
}
.archive-scroll::-webkit-scrollbar { display: none; }
.archive-scroll > * { flex: 0 0 auto; width: 32vw; max-width: 150px; scroll-snap-align: start; }

.view-more-card {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: .4rem;
  aspect-ratio: 2 / 3; text-align: center; background: var(--bg-drawer);
  border: 1px dashed var(--line); border-radius: 4px; color: var(--muted);
  font-family: var(--font-mono), monospace; font-size: .72rem; letter-spacing: .03em; padding: .75rem;
}
.view-more-card:hover { color: var(--ink); border-color: var(--accent); }
.view-more-arrow { font-size: 1.25rem; }

.feed-note {
  padding: 1.5rem; color: var(--muted); font-family: var(--font-mono), monospace; font-size: .78rem;
}
.feed-note button {
  background: none; border: 1px solid var(--line); color: var(--ink-soft);
  padding: .3rem .7rem; border-radius: 3px; font: inherit; cursor: pointer; margin-left: .4rem;
}
.feed-note button:hover { border-color: var(--accent); }

.skel {
  aspect-ratio: 2 / 3; border-radius: 6px;
  background: linear-gradient(100deg, var(--bg-drawer) 30%, var(--card) 50%, var(--bg-drawer) 70%);
  background-size: 200% 100%; animation: aa-sh 1.4s infinite linear;
}
@keyframes aa-sh { to { background-position: -200% 0; } }

.empty-state {
  max-width: 1200px; margin: 0 auto; padding: 3rem 1.5rem;
  color: var(--ink-soft); font-family: var(--font-mono), monospace; font-size: .85rem; text-align: center;
}

/* ---------- Poster cards ---------- */
.poster-grid {
  max-width: 1200px; margin: 0 auto; padding: 1.25rem 1rem;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem .75rem;
}
.poster-card {
  display: flex; flex-direction: column; gap: .4rem; color: var(--ink);
  transition: transform .15s ease; min-width: 0;
}
.poster-card:hover { transform: translateY(-3px); }
.poster-art {
  position: relative; width: 100%; aspect-ratio: 2 / 3; border-radius: 6px;
  overflow: hidden; background: var(--bg-drawer); box-shadow: 0 6px 18px rgba(0,0,0,.45);
}
.poster-art img { width: 100%; height: 100%; object-fit: cover; }
.art-ph {
  display: block; width: 100%; height: 100%;
  background: linear-gradient(150deg, #231B45, #141827 65%, #1d1236);
}
.poster-format-tag {
  position: absolute; top: 8px; right: 8px; background: #3B82F6; color: #fff;
  font-family: var(--font-mono), monospace; font-size: .62rem; font-weight: 700;
  letter-spacing: .04em; padding: .2rem .4rem; border-radius: 3px;
}
.poster-overlay-bar {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; justify-content: space-between; align-items: center;
  background: linear-gradient(to top, rgba(0,0,0,.85), rgba(0,0,0,0));
  padding: 1.1rem .4rem .4rem;
}
.poster-episodes-tag {
  background: rgba(124, 58, 237, .9); color: #fff;
  font-family: var(--font-mono), monospace; font-size: .62rem; font-weight: 600;
  padding: .18rem .4rem; border-radius: 3px; letter-spacing: .02em;
}
.poster-title {
  font-family: var(--font-display), serif; font-weight: 600; font-size: .95rem;
  line-height: 1.25; margin: 0; color: var(--ink);
  overflow-wrap: break-word; word-break: break-word; min-width: 0;
}
.poster-meta-row {
  display: flex; justify-content: space-between; align-items: baseline; gap: .5rem;
  font-family: var(--font-mono), monospace; font-size: .68rem; letter-spacing: .02em; color: var(--muted);
}
.poster-labels-raw { display: none; }

/* ---------- Genre browse / chips ---------- */
.genre-browse-section { max-width: 1200px; margin: .5rem auto 2.5rem; padding: 0 1.25rem; }
.genre-browse-section .section-title { padding: 0; margin: 2rem 0 0; }
.genre-browse-grid { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: .75rem; }
.genre-nav-item {
  font-family: var(--font-mono), monospace; font-size: .72rem; letter-spacing: .03em;
  color: var(--muted); border: 1px solid var(--line); padding: .35rem .7rem; border-radius: 999px;
  transition: color .15s, border-color .15s;
}
.genre-nav-item:hover, .genre-nav-item.on { color: var(--ink); border-color: var(--accent); }
.genre-chip {
  display: inline-block; font-family: var(--font-mono), monospace; font-size: .68rem;
  border: 1px solid var(--muted); border-radius: 3px; padding: .2rem .5rem; color: var(--ink-soft);
}
.genre-chip:hover { border-color: var(--accent); color: var(--accent-text); }
.stamp {
  display: inline-block; font-family: var(--font-mono), monospace; font-size: .68rem;
  font-weight: 700; letter-spacing: .05em; padding: .2rem .5rem; border-radius: 3px;
  background: #3B82F6; color: #fff;
}
.stamp.status { background: var(--accent); }
.listing-chips {
  max-width: 1200px; margin: 1rem auto 0; padding: 0 1.25rem;
  display: flex; flex-direction: column; gap: .5rem;
}
.chip-row { display: flex; gap: .5rem; overflow-x: auto; padding-bottom: 2px; scrollbar-width: none; }
.chip-row::-webkit-scrollbar { display: none; }
.chip-row .genre-nav-item { white-space: nowrap; }

/* ---------- Pagination ---------- */
.pagination-row {
  max-width: 1200px; margin: .5rem auto 2.5rem; padding: 0 1.25rem;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .4rem;
  font-family: var(--font-mono), monospace; font-size: .78rem;
}
.pagination-btn {
  border: 1px solid var(--line); color: var(--muted); padding: .5rem .9rem; border-radius: 4px;
  transition: color .15s, border-color .15s;
}
.pagination-btn:hover { color: var(--ink); border-color: var(--accent); }

/* ---------- Article ledger ---------- */
.ledger { max-width: 960px; margin: 0 auto; padding: 1.75rem 1.25rem 4rem; }
.ledger-back {
  display: flex; flex-wrap: wrap; gap: .4rem; list-style: none; margin: 0 0 1.4rem; padding: 0;
  font-family: var(--font-mono), monospace; font-size: .8rem; color: var(--muted);
}
.ledger-back li + li::before { content: "/"; margin-right: .4rem; color: var(--line); }
.ledger-back a:hover { color: var(--ink); }
.ledger-back li:last-child { max-width: 36ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.ledger-sheet {
  background: var(--card); color: var(--ink); border-radius: 8px; padding: 2rem;
  box-shadow: 0 10px 30px rgba(0,0,0,.4);
}
.ledger-grid { display: grid; grid-template-columns: 220px 1fr; gap: 1.75rem; }
.ledger-grid.no-art { grid-template-columns: 1fr; }
.ledger-art {
  position: relative; border-radius: 4px; overflow: hidden; aspect-ratio: 2 / 3;
  background: var(--bg-drawer); box-shadow: 0 6px 18px rgba(0,0,0,.35);
}
.ledger-art img { width: 100%; height: 100%; object-fit: cover; }
.ledger-title {
  font-family: var(--font-display), serif; font-weight: 900; font-size: 2rem; line-height: 1.15; margin: 0 0 .5rem;
}
.ledger-stamps { display: flex; flex-wrap: wrap; gap: .4rem; margin-bottom: .9rem; }
.ledger-meta {
  display: flex; flex-wrap: wrap; gap: .3rem 1rem;
  font-family: var(--font-mono), monospace; font-size: .74rem; color: var(--muted); margin-bottom: .6rem;
}
.ledger-genres { display: flex; flex-wrap: wrap; gap: .4rem; margin-top: .8rem; }
.ledger-intro { font-size: .95rem; line-height: 1.6; color: var(--muted); margin-top: 1rem; }
.aa-spoiler {
  margin: 1.5rem 0 0; padding: .8rem 1rem; color: #FDE68A; font-size: .85rem;
  background: rgba(245,158,11,.08); border: 1px solid rgba(245,158,11,.35); border-radius: 4px;
}
.ledger-body { margin-top: 1.75rem; padding-top: 1.5rem; border-top: 1px solid var(--line); }

/* TOC */
.aa-toc {
  margin: 0 0 1.75rem; padding: 1rem 1.2rem; background: var(--bg-drawer);
  border: 1px solid var(--line); border-radius: 4px;
}
.aa-toc > summary, .aa-toc > h3 {
  cursor: pointer; font-family: var(--font-mono), monospace; font-size: .78rem;
  letter-spacing: .05em; color: var(--muted); font-weight: 500; list-style: none;
}
.aa-toc ol, .aa-toc ul { margin: .8rem 0 0; padding-left: 1.2rem; }
.aa-toc li { margin: .35rem 0; font-size: .9rem; }
.aa-toc li.l3 { margin-left: 1rem; font-size: .84rem; }
.aa-toc a { color: var(--ink-soft); }
.aa-toc a:hover { color: var(--accent-text); }

/* Article content */
.aa-content { font-size: 1.02rem; line-height: 1.8; overflow-wrap: anywhere; color: var(--ink-soft); }
.aa-content h2 {
  font-family: var(--font-display), serif; font-weight: 600; font-size: 1.5rem;
  margin: 2.2em 0 .6em; padding-bottom: .35em; border-bottom: 1px solid var(--line);
  color: var(--ink); scroll-margin-top: 5rem;
}
.aa-content h3 {
  font-family: var(--font-display), serif; font-weight: 600; font-size: 1.2rem;
  margin: 1.8em 0 .5em; color: var(--ink); scroll-margin-top: 5rem;
}
.aa-content h4 {
  font-family: var(--font-display), serif; font-size: 1.05rem;
  margin: 1.5em 0 .4em; color: var(--ink);
}
.aa-content p { margin: 1.05em 0; }
.aa-content ul, .aa-content ol { margin: 1.05em 0; padding-left: 1.5em; }
.aa-content li { margin: .4em 0; }
.aa-content strong, .aa-content b { color: var(--ink); }
.aa-content a {
  color: var(--accent-text); text-decoration: underline; text-underline-offset: 3px;
  text-decoration-color: rgba(167,139,250,.4);
}
.aa-content a:hover { color: #fff; }
.aa-content img { border-radius: 4px; cursor: zoom-in; }
.aa-content figure { margin: 1.6em 0; text-align: center; }
.aa-content figcaption, .aa-content .tr-caption {
  color: var(--muted); font-family: var(--font-mono), monospace; font-size: .75rem; margin-top: .5rem;
}
.aa-content .separator, .aa-content .tr-caption-container { text-align: center; }
.aa-content .separator a, .aa-content a[imageanchor] { margin: 0 !important; text-decoration: none; }
.aa-content blockquote {
  margin: 1.5em 0; padding: .2em 0 .2em 1.1em; color: var(--muted);
  border-left: 3px solid var(--accent); font-style: italic;
}
.aa-content iframe, .aa-content video { max-width: 100%; border: 0; border-radius: 4px; }
.aa-content hr { border: 0; border-top: 1px solid var(--line); margin: 2.2em 0; }
.aa-table-wrap { overflow-x: auto; margin: 1.5em 0; border: 1px solid var(--line); border-radius: 4px; }
.aa-content table { border-collapse: collapse; width: 100%; min-width: 460px; font-size: .9rem; }
.aa-content th, .aa-content td { padding: .6rem .8rem; text-align: left; border-bottom: 1px solid var(--line); }
.aa-content th { background: var(--bg-drawer); color: var(--ink); font-weight: 600; }
.aa-content pre, .aa-content code {
  background: var(--bg-drawer); border-radius: 4px; font-family: var(--font-mono), monospace; font-size: .88em;
}
.aa-content code { padding: .1em .4em; }
.aa-content pre { padding: .9rem; overflow-x: auto; }

/* Bot article contract */
.aa-content .aa-article { background: none; border: 0; padding: 0; margin: 0; }
.aa-content .aa-article-header { margin: 0; padding: 0; border: 0; }
.aa-content .aa-article-header h1, .aa-content .aa-article-header .aa-category { display: none; }
.aa-content .aa-intro {
  color: var(--muted); font-style: italic; border-left: 3px solid var(--accent);
  padding-left: 1rem; margin: 0 0 1.5em;
}
.aa-content .aa-related { margin-top: 2.5em; padding-top: 1.4em; border-top: 1px solid var(--line); }
.aa-content .aa-chapter-nav, .aa-content .aa-nav-links {
  display: flex; justify-content: space-between; gap: .75rem; margin: 2em 0;
}
.aa-content .aa-chapter-nav a, .aa-content .aa-nav-links a {
  text-decoration: none; padding: .6rem 1rem; border: 1px solid var(--line);
  border-radius: 4px; background: var(--bg-drawer); color: var(--ink);
}

/* ---------- Type-aware article templates ---------- */
.ledger-sheet[data-type] { position: relative; }

/* --- Series (Anime / Manga / Manhwa / Manhua / Donghua) --- */
.ledger-sheet[data-type="TYPE_Anime"] .ledger-art,
.ledger-sheet[data-type="TYPE_Manga"] .ledger-art,
.ledger-sheet[data-type="TYPE_Manhwa"] .ledger-art,
.ledger-sheet[data-type="TYPE_Manhua"] .ledger-art,
.ledger-sheet[data-type="TYPE_Donghua"] .ledger-art,
.ledger-sheet[data-type="TYPE_Webtoon"] .ledger-art,
.ledger-sheet[data-type="TYPE_LightNovel"] .ledger-art {
  box-shadow: 0 10px 32px rgba(0,0,0,.5);
}
.ledger-sheet.is-series .ledger-title { font-size: clamp(1.7rem, 3.5vw, 2.15rem); }

/* --- Character profile --- */
.ledger-sheet[data-type="TYPE_Character"] .ledger-grid {
  grid-template-columns: 240px 1fr;
}
.ledger-sheet[data-type="TYPE_Character"] .ledger-art {
  border-radius: 10px; box-shadow: 0 10px 36px rgba(124,58,237,.3);
  border: 2px solid rgba(124,58,237,.25);
}
.ledger-sheet[data-type="TYPE_Character"] .ledger-title {
  font-size: clamp(1.6rem, 3.2vw, 2rem);
}
.ledger-sheet[data-type="TYPE_Character"] .ledger-stamps .stamp:first-child {
  background: linear-gradient(135deg, #7C3AED, #A78BFA);
}
.aa-char-alias {
  font-family: var(--font-mono), monospace; font-size: .8rem; color: var(--muted);
  margin: -.25rem 0 .6rem; font-style: italic;
}

/* --- News --- */
.ledger-sheet[data-type="TYPE_News"] .ledger-grid { grid-template-columns: 1fr; }
.ledger-sheet[data-type="TYPE_News"] .ledger-art {
  aspect-ratio: 16 / 9; max-height: 320px; max-width: 100%;
  border-radius: 6px; margin-bottom: .25rem;
}
.ledger-sheet[data-type="TYPE_News"] .ledger-title {
  font-size: clamp(1.55rem, 3.2vw, 2rem); max-width: 42ch;
}
.aa-news-byline {
  display: flex; flex-wrap: wrap; gap: .35rem 1rem;
  font-family: var(--font-mono), monospace; font-size: .74rem; color: var(--muted);
  margin-bottom: .75rem; padding-bottom: .75rem; border-bottom: 1px solid var(--line);
}
.aa-news-byline .news-cat {
  color: var(--accent-text); font-weight: 600; letter-spacing: .04em; text-transform: uppercase;
  font-size: .68rem;
}

/* --- Ranking / Guide --- */
.ledger-sheet[data-type="TYPE_Ranking"] .ledger-stamps,
.ledger-sheet[data-type="TYPE_Guide"] .ledger-stamps {
  align-items: center;
}
.aa-rank-badge {
  display: inline-flex; align-items: center; gap: .35rem;
  background: linear-gradient(135deg, #7C3AED, #5B21B6);
  color: #fff; font-family: var(--font-mono), monospace; font-size: .7rem;
  font-weight: 700; letter-spacing: .06em; padding: .3rem .7rem; border-radius: 4px;
  margin-bottom: .6rem;
}
.ledger-sheet[data-type="TYPE_Guide"] .aa-rank-badge {
  background: linear-gradient(135deg, #2563EB, #1D4ED8);
}

/* --- Chapter / Volume / Story Arc --- */
.ledger-sheet[data-type="TYPE_Chapter"] .aa-spoiler,
.ledger-sheet[data-type="TYPE_Volume"] .aa-spoiler,
.ledger-sheet[data-type="TYPE_StoryArc"] .aa-spoiler { display: block !important; }
.aa-chapter-context {
  display: flex; flex-wrap: wrap; align-items: center; gap: .5rem .85rem;
  margin: 0 0 1rem; padding: .7rem 1rem;
  background: rgba(124,58,237,.08); border: 1px solid rgba(124,58,237,.3);
  border-radius: 4px; font-family: var(--font-mono), monospace; font-size: .78rem;
}
.aa-chapter-context .cc-series {
  color: var(--accent-text); font-weight: 600;
}
.aa-chapter-context .cc-series:hover { color: #fff; }
.aa-chapter-context .cc-sep { color: var(--line); }
.aa-chapter-context .cc-meta { color: var(--muted); }

/* Shared type UI */
.aa-type-bar {
  display: flex; flex-wrap: wrap; gap: .5rem 1.25rem; margin: 1rem 0 0;
  padding: .85rem 1rem; background: var(--bg-drawer); border: 1px solid var(--line);
  border-radius: 4px; font-family: var(--font-mono), monospace; font-size: .74rem; color: var(--muted);
}
.aa-type-bar strong { color: var(--ink-soft); font-weight: 500; margin-right: .25rem; }
.aa-type-bar a { color: var(--accent-text); }
.aa-type-bar a:hover { color: #fff; }

.aa-series-nav {
  display: flex; flex-wrap: wrap; gap: .5rem; margin: 1.5rem 0 0;
  padding: 1rem; background: var(--bg-drawer); border: 1px solid var(--line); border-radius: 4px;
}
.aa-series-nav .sn-label {
  width: 100%; font-family: var(--font-mono), monospace; font-size: .68rem;
  letter-spacing: .05em; color: var(--muted); margin-bottom: .25rem;
}
.aa-series-nav a {
  font-family: var(--font-mono), monospace; font-size: .78rem; color: var(--ink-soft);
  border: 1px solid var(--line); padding: .4rem .75rem; border-radius: 4px;
  transition: border-color .15s, color .15s;
}
.aa-series-nav a:hover { border-color: var(--accent); color: var(--ink); }
.aa-series-nav a.current { border-color: var(--accent); background: rgba(124,58,237,.15); color: var(--accent-text); }

.aa-fact-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: .55rem; margin: 1.1rem 0 0;
}
.aa-fact {
  background: var(--bg-drawer); border: 1px solid var(--line); border-radius: 4px;
  padding: .55rem .7rem; font-family: var(--font-mono), monospace; font-size: .72rem;
}
.aa-fact span {
  display: block; color: var(--muted); font-size: .62rem;
  letter-spacing: .04em; margin-bottom: .15rem; text-transform: uppercase;
}
.aa-fact strong { color: var(--ink); font-weight: 500; word-break: break-word; }
.aa-fact a { color: var(--accent-text); }
.aa-fact a:hover { color: #fff; }

.related-box .section-sub { padding: 0; margin: .25rem 0 0; }
.aa-related-tabs {
  display: flex; gap: .4rem; margin: 1rem 0 0; flex-wrap: wrap;
}
.aa-related-tabs button {
  font-family: var(--font-mono), monospace; font-size: .7rem; letter-spacing: .03em;
  background: transparent; border: 1px solid var(--line); color: var(--muted);
  padding: .3rem .7rem; border-radius: 999px; cursor: pointer;
}
.aa-related-tabs button.on, .aa-related-tabs button:hover {
  border-color: var(--accent); color: var(--ink);
}

@media (max-width: 640px) {
  .ledger-sheet[data-type="TYPE_Character"] .ledger-grid { grid-template-columns: 1fr; }
  .ledger-sheet[data-type="TYPE_Character"] .ledger-art { max-width: 220px; margin: 0 auto; }
}

/* Share + post nav */
.aa-share {
  display: flex; flex-wrap: wrap; align-items: center; gap: .5rem;
  margin-top: 2.2rem; padding-top: 1.2rem; border-top: 1px solid var(--line);
  font-family: var(--font-mono), monospace; font-size: .74rem; color: var(--muted);
}
.aa-share a, .aa-share button {
  font: inherit; color: var(--muted); background: none; border: 1px solid var(--line);
  padding: .35rem .75rem; border-radius: 999px; cursor: pointer; transition: color .15s, border-color .15s;
}
.aa-share a:hover, .aa-share button:hover { color: var(--ink); border-color: var(--accent); }
.post-nav { display: grid; grid-template-columns: 1fr; gap: .6rem; margin-top: 1.4rem; }
.post-nav a {
  display: block; padding: .85rem 1rem; background: var(--bg-drawer);
  border: 1px solid var(--line); border-radius: 4px; font-size: .9rem; transition: border-color .15s;
}
.post-nav a:hover { border-color: var(--accent); }
.post-nav small {
  display: block; font-family: var(--font-mono), monospace; color: var(--muted);
  font-size: .68rem; margin-bottom: 2px;
}
.post-nav .next { text-align: right; }
.related-box .section-title { padding: 0; margin: 2.5rem 0 0; }
.related-box .poster-grid { padding: 1rem 0 0; }

/* Comments */
.aa-comments {
  margin-top: 2.5rem; padding-top: 1.5rem; border-top: 1px solid var(--line);
}
.aa-comments-title {
  font-family: var(--font-display), serif; font-weight: 600; font-size: 1.25rem;
  margin: 0 0 1rem; color: var(--ink);
}
.aa-comments .comment-form, .aa-comments #comment-form,
.aa-comments .comments, .aa-comments .comment {
  font-family: var(--font-body), sans-serif; color: var(--ink-soft);
}
.aa-comments iframe { max-width: 100%; border-radius: 4px; }
.aa-comments a { color: var(--accent-text); }
.aa-comments .comment-actions a, .aa-comments .continue { color: var(--muted); }
.aa-comments input, .aa-comments textarea {
  background: var(--bg-drawer); border: 1px solid var(--line); color: var(--ink);
  border-radius: 4px; padding: .5rem .7rem; font: inherit;
}
.aa-comments button, .aa-comments .comment-submit {
  background: var(--accent); color: #fff; border: 0; border-radius: 4px;
  padding: .5rem 1rem; font-family: var(--font-mono), monospace; font-size: .78rem;
  cursor: pointer;
}

/* Lightbox */
.aa-lightbox {
  position: fixed; inset: 0; z-index: 600; background: rgba(0,0,0,.92);
  display: flex; align-items: center; justify-content: center; padding: 1.5rem;
  opacity: 0; visibility: hidden; transition: opacity .2s, visibility .2s; cursor: zoom-out;
}
.aa-lightbox.open { opacity: 1; visibility: visible; }
.aa-lightbox img { max-width: 100%; max-height: 90vh; border-radius: 4px; object-fit: contain; }
.aa-lightbox-close {
  position: absolute; top: 1rem; right: 1rem; width: 40px; height: 40px;
  background: var(--card); border: 1px solid var(--line); border-radius: 4px;
  color: var(--ink); font-size: 1.3rem; cursor: pointer; display: flex;
  align-items: center; justify-content: center;
}

/* Back to top */
.aa-top {
  position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 200;
  width: 42px; height: 42px; border-radius: 50%; background: var(--accent);
  color: #fff; border: 0; cursor: pointer; opacity: 0; visibility: hidden;
  transition: opacity .2s, visibility .2s, transform .15s;
  display: flex; align-items: center; justify-content: center; font-size: 1.1rem;
  box-shadow: 0 4px 14px rgba(124,58,237,.4);
}
.aa-top.show { opacity: 1; visibility: visible; }
.aa-top:hover { transform: translateY(-2px); }

/* 404 */
.notfound { text-align: center; padding: 5rem 1.5rem; }
.notfound h1 { font-family: var(--font-display), serif; font-weight: 900; font-size: 2.6rem; margin-bottom: .5rem; }
.notfound p { color: var(--muted); font-family: var(--font-mono), monospace; font-size: .85rem; }
.btn {
  display: inline-block; margin-top: 1.2rem; background: var(--accent); color: #fff;
  padding: .7rem 1.2rem; border-radius: 4px; font-family: var(--font-mono), monospace; font-size: .8rem;
}
.btn:hover { background: var(--accent-hover); color: #fff; }

/* ---------- Footer ---------- */
.site-footer {
  margin-top: auto; border-top: 1px solid var(--line);
  padding: 2rem 1.5rem; text-align: center;
  font-family: var(--font-mono), monospace; font-size: .7rem; color: var(--muted);
}
.footer-links {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .3rem 1.2rem; margin-bottom: 1rem;
}
.footer-links a:hover { color: var(--ink); }
.footer-brand {
  font-family: var(--font-display), serif; font-weight: 700; font-size: .85rem;
  color: var(--ink-soft); margin-bottom: .5rem;
}

/* ---------- Browse button (collapsible section list) ---------- */
.browse-menu { margin-top: 1rem; }
.browse-btn {
  list-style: none; display: flex; align-items: center; justify-content: space-between; gap: .75rem;
  padding: .95rem 1.1rem; cursor: pointer; user-select: none;
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  font-family: var(--font-display), serif; font-size: 1.25rem; font-weight: 600; color: var(--ink);
  transition: border-color .15s;
}
.browse-btn::-webkit-details-marker { display: none; }
.browse-btn:hover, .browse-btn:focus-visible, .browse-menu[open] > .browse-btn { border-color: var(--accent); }
.browse-btn .chev { font-size: .8rem; color: var(--accent-text); transition: transform .2s; }
.browse-menu[open] > .browse-btn .chev { transform: rotate(180deg); }
.browse-list {
  display: flex; flex-direction: column; margin-top: .5rem;
  background: var(--bg-drawer); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden;
}
.browse-item {
  display: flex; align-items: baseline; gap: .75rem; padding: .85rem 1.1rem;
  border-bottom: 1px solid var(--line); background: transparent;
  transition: background .15s, padding-left .15s;
}
.browse-item:last-child { border-bottom: 0; }
.browse-item::after { content: '›'; margin-left: auto; color: var(--muted); font-size: 1.1rem; }
.browse-item:hover, .browse-item:focus-visible { background: var(--card); padding-left: 1.4rem; }
.browse-item:hover::after, .browse-item:focus-visible::after { color: var(--accent-text); }
.browse-item span { font-family: var(--font-body), sans-serif; font-weight: 500; font-size: .98rem; color: var(--ink); }
.browse-item small { font-family: var(--font-mono), monospace; font-size: .68rem; color: var(--muted); }
@media (min-width: 640px) { .browse-menu { max-width: 420px; } }

/* ---------- Stray Blogger default widgets ---------- */
/* The theme has its own header, search and navigation, so Blogger's default Header / Search /
   Archive / Report Abuse widgets are hidden wherever Blogger placed them. */
.aa-main-section .widget:not(.Blog),
.widget.Label, .aa-extra .widget.Header, .aa-extra .widget.BlogSearch, .aa-extra .widget.BlogArchive,
.aa-extra .widget.ReportAbuse, .aa-extra .widget.Profile { display: none !important; }

/* ---------- Tags: vertical list with a vertical rule (Anime-Planet style) ---------- */
.ledger-genres { display: block; margin-top: 1.1rem; }
.ledger-genres::before {
  content: 'Tags'; display: block; margin-bottom: .45rem;
  font-family: var(--font-mono), monospace; font-size: .68rem; letter-spacing: .1em;
  text-transform: uppercase; color: var(--muted);
}
.ledger-genres a, .ledger-genres .genre-chip {
  display: block; background: transparent; border: 0; border-left: 2px solid var(--line); border-radius: 0;
  padding: .32rem 0 .32rem .9rem; margin: 0;
  font-family: var(--font-body), sans-serif; font-size: .88rem; letter-spacing: 0; text-transform: none; color: var(--ink-soft);
  transition: color .15s, border-color .15s;
}
.ledger-genres a:hover, .ledger-genres a:focus-visible { color: var(--accent-text); border-left-color: var(--accent); background: transparent; }

/* ---------- Responsive ---------- */
@media (min-width: 640px) {
  .archive-scroll > * { width: 22vw; max-width: 180px; }
  .poster-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .post-nav { grid-template-columns: 1fr 1fr; }
  .cat-grid { grid-template-columns: repeat(4, 1fr); }
  .hero-card { min-height: 380px; }
}
@media (min-width: 900px) {
  .nav-desktop { display: flex; }
  .menu-toggle { display: none; }
  .hero-card { grid-template-columns: 1.1fr 1fr; min-height: 420px; }
  .hero-content { padding: 2.5rem; justify-content: center; }
  .hero-bg img { opacity: .55; }
}
@media (min-width: 1024px) {
  .archive-scroll > * { width: 200px; max-width: 200px; }
  .poster-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1.5rem 1rem; }
  .cat-grid { grid-template-columns: repeat(4, 1fr); gap: 1rem; }
}
@media (max-width: 640px) {
  .ledger-grid { grid-template-columns: 1fr; }
  .ledger-art { max-width: 200px; margin: 0 auto; }
  .ledger-sheet { padding: 1.25rem; }
  .ledger-title { font-size: 1.55rem; }
  .header-bar { padding: 0 1rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}
@media print {
  .site-header, .site-footer, .aa-share, .post-nav, .related-box, .aa-progress, .aa-top, .drawer, .drawer-backdrop, .search-overlay { display: none !important; }
  body { background: #fff; color: #000; }
  .ledger-sheet { box-shadow: none; border: 1px solid #ccc; }
}

body.script:
//
(function () {
  'use strict';
  var D = document, W = window, ORIGIN = W.location.origin;

  /* ---------- Config ---------- */
  var CFG = {
    special: ['FEATURED', 'TRENDING'],
    related: 5,
    spoilerTypes: ['TYPE_Chapter', 'TYPE_Volume', 'TYPE_StoryArc'],
    genres: ['Action', 'Adventure', 'Comedy', 'Drama', 'Fantasy', 'Horror', 'Romance', 'SciFi', 'Thriller', 'SliceOfLife', 'Supernatural', 'Mystery'],
    titles: {
      TYPE_Chapter: 'Chapters', TYPE_Volume: 'Volumes', TYPE_StoryArc: 'Story Arcs',
      TYPE_Webtoon: 'Webtoons', TYPE_LightNovel: 'Light Novels', TYPE_WebNovel: 'Web Novels',
      TYPE_Character: 'Characters', TYPE_Guide: 'Recommendations', TYPE_Ranking: 'Rankings',
      TYPE_News: 'News', TYPE_Anime: 'Anime', TYPE_Manga: 'Manga', TYPE_Manhwa: 'Manhwa',
      TYPE_Manhua: 'Manhua', TYPE_Donghua: 'Donghua',
      STATUS_Upcoming: 'Upcoming', STATUS_Ongoing: 'Ongoing', STATUS_Completed: 'Completed',
      STATUS_OnHiatus: 'On Hiatus', TRENDING: 'Trending', FEATURED: 'Featured'
    },
    subs: {
      TYPE: 'Every article in this category.',
      STATUS: 'Filtered by release status.',
      GENRE: 'Series and articles in this genre.',
      SPECIAL: 'Curated selection.'
    },
    chips: [
      ['TYPE_Anime', 'TYPE_Manga', 'TYPE_Manhwa', 'TYPE_Manhua', 'TYPE_Donghua', 'TYPE_Webtoon', 'TYPE_LightNovel', 'TYPE_WebNovel', 'TYPE_Character', 'TYPE_News'],
      ['STATUS_Ongoing', 'STATUS_Completed', 'STATUS_Upcoming', 'STATUS_OnHiatus']
    ]
  };

  /* ---------- Helpers ---------- */
  function $(s, r) { return (r || D).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || D).querySelectorAll(s)); }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function on(el, ev, fn) { if (el) el.addEventListener(ev, fn); }
  function kind(l) {
    if (/^SERIES_/.test(l)) return 'SERIES';
    var m = /^(TYPE|STATUS|GENRE)_/.exec(l);
    if (m) return m[1];
    if (CFG.special.indexOf(l) > -1) return 'SPECIAL';
    return 'OTHER'; // plain labels are not auto-treated as series
  }
  function pretty(l) {
    return CFG.titles[l] || String(l)
      .replace(/^(TYPE|STATUS|GENRE|SERIES)_/, '')
      .replace(/([a-z])([A-Z])/g, '$1 $2')
      .replace(/_/g, ' ');
  }
  function single(l) { var p = pretty(l); return p === 'News' ? p : p.replace(/s$/, ''); }
  function labelUrl(l) { return '/search/label/' + encodeURIComponent(l); }
  function getJSON(url, retries) {
    function attempt(n) {
      return fetch(url, { signal: AbortSignal.timeout ? AbortSignal.timeout(10000) : undefined })
        .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
        .catch(function (err) {
          if (n > 0) return new Promise(function (res) { setTimeout(res, 700); }).then(function () { return attempt(n - 1); });
          throw err;
        });
    }
    return attempt(retries || 0);
  }
  function pick(labels) {
    var o = { type: '', status: '' };
    (labels || []).forEach(function (l) {
      var k = kind(l);
      if (k === 'TYPE' && !o.type) o.type = l;
      if (k === 'STATUS' && !o.status) o.status = l;
    });
    return o;
  }

  /* ---------- Head meta helpers (no duplicate tags) ---------- */
  function metaSel(attr, key) { return 'meta[' + attr + '="' + key + '"]'; }
  function setMeta(attr, key, val) {
    if (!val) return;
    var el = $(metaSel(attr, key), D.head);
    if (!el) { el = D.createElement('meta'); el.setAttribute(attr, key); D.head.appendChild(el); }
    el.setAttribute('content', val);
  }
  function fill(attr, key, val) { // set only when Blogger did not already provide a value
    if (!val) return;
    var el = $(metaSel(attr, key), D.head);
    if (el && (el.getAttribute('content') || '').trim()) return;
    setMeta(attr, key, val);
  }
  function ensureCanonical(url) { // create only if Blogger did not emit one; never override
    var link = $('link[rel="canonical"]', D.head);
    if (!link) { link = D.createElement('link'); link.rel = 'canonical'; link.href = url; D.head.appendChild(link); }
    return link.href;
  }
  function dedupeHead() {
    var sels = [
      'link[rel="canonical"]',
      metaSel('name', 'description'),
      metaSel('property', 'og:title'), metaSel('property', 'og:type'), metaSel('property', 'og:url'),
      metaSel('property', 'og:image'), metaSel('property', 'og:description'), metaSel('property', 'og:site_name'),
      metaSel('name', 'twitter:card'), metaSel('name', 'twitter:title'), metaSel('name', 'twitter:description'),
      metaSel('name', 'twitter:image'), metaSel('name', 'twitter:url')
    ];
    sels.forEach(function (sel) {
      var els = $$(sel, D.head);
      if (els.length < 2) return;
      var keep = els.filter(function (e) { return (e.getAttribute('content') || e.getAttribute('href') || '').trim(); })[0] || els[0];
      els.forEach(function (e) { if (e !== keep && e.parentNode) e.parentNode.removeChild(e); });
    });
  }
  function headDefaults() {
    var home = $('#aaHome'), lt0 = $('#aaLabelTitle');
    fill('property', 'og:site_name', 'ANIME ARCHIVE');
    fill('name', 'twitter:card', 'summary_large_image');
    if (home) {
      var hd = 'Browse anime, manga, manhwa, manhua, characters, chapters and news. A curated encyclopedia powered by Blogger.';
      var ht = 'ANIME ARCHIVE — anime, manga, manhwa and manhua encyclopedia';
      fill('name', 'description', hd); fill('property', 'og:description', hd); fill('name', 'twitter:description', hd);
      fill('property', 'og:title', ht); fill('name', 'twitter:title', ht);
      fill('property', 'og:type', 'website'); fill('property', 'og:url', ORIGIN + '/');
    } else if (lt0) {
      var ln = pretty(lt0.textContent.trim());
      var ldesc = 'Browse all ' + ln + ' articles on ANIME ARCHIVE.';
      var lurl = W.location.href.split('?')[0].split('#')[0];
      setMeta('name', 'description', ldesc); setMeta('property', 'og:description', ldesc); setMeta('name', 'twitter:description', ldesc);
      setMeta('property', 'og:title', ln + ' — ANIME ARCHIVE'); setMeta('name', 'twitter:title', ln + ' — ANIME ARCHIVE');
      setMeta('property', 'og:type', 'website'); setMeta('property', 'og:url', lurl);
    } else if ($('#aaListing') && !$('#aaPost')) {
      var q = ''; try { q = new URLSearchParams(W.location.search).get('q') || ''; } catch (e) {}
      if (q) {
        setMeta('name', 'description', 'Search results for "' + q + '" on ANIME ARCHIVE.');
        setMeta('property', 'og:title', 'Search results for ' + q + ' — ANIME ARCHIVE');
      }
    }
  }
  dedupeHead();

  /* ---------- Complete paginated feed fetch (parallel pages, cached) ---------- */
  var PAGE_SIZE = 150, MAX_PAGES = 20, CACHE_TTL = 10 * 60 * 1000;
  function cacheGet(k) {
    try {
      var o = JSON.parse(W.sessionStorage.getItem('aa:' + k) || 'null');
      return o && Date.now() - o.t < CACHE_TTL ? o.v : null;
    } catch (e) { return null; }
  }
  function cacheSet(k, v) {
    try { W.sessionStorage.setItem('aa:' + k, JSON.stringify({ t: Date.now(), v: v })); } catch (e) { /* quota / private mode */ }
  }
  // Fetches EVERY entry of a summary feed until it is exhausted (safety cap: MAX_PAGES * PAGE_SIZE).
  // Resolves { items, complete }. Only complete results are cached.
  function fetchAllPosts(basePath) {
    var cached = cacheGet(basePath);
    if (cached) return Promise.resolve({ items: cached, complete: true });
    var complete = true;
    function pageUrl(i) { return basePath + '?alt=json&max-results=' + PAGE_SIZE + '&start-index=' + (i * PAGE_SIZE + 1); }
    function entriesOf(j) { return (j.feed && j.feed.entry) || []; }
    function sequential(i, acc) { // used only if the feed reports no total
      if (i >= MAX_PAGES) { complete = false; return Promise.resolve(acc); }
      return getJSON(pageUrl(i), 1).then(function (j) {
        var e = entriesOf(j);
        acc = acc.concat(e);
        return e.length >= PAGE_SIZE ? sequential(i + 1, acc) : acc;
      }).catch(function () { complete = false; return acc; });
    }
    return getJSON(pageUrl(0), 1).then(function (first) {
      var entries = entriesOf(first);
      if (entries.length < PAGE_SIZE) return entries;
      var tot = first.feed && first.feed['openSearch$totalResults'];
      var total = tot ? parseInt(tot.$t, 10) : NaN;
      if (isNaN(total)) return sequential(1, entries);
      var pages = Math.ceil(total / PAGE_SIZE);
      if (pages > MAX_PAGES) { pages = MAX_PAGES; complete = false; }
      var jobs = [];
      for (var i = 1; i < pages; i++) {
        jobs.push(getJSON(pageUrl(i), 1).then(entriesOf).catch(function () { complete = false; return []; }));
      }
      return Promise.all(jobs).then(function (rest) { return entries.concat.apply(entries, rest); });
    }).then(function (entries) {
      var items = entries.map(norm).map(function (p) { delete p.summary; return p; });
      if (complete) cacheSet(basePath, items);
      return { items: items, complete: complete };
    });
  }

  /* ---------- Modal helpers: focus trap, inert background, focus restore ---------- */
  var FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
  var frame = $('.archive-frame');
  var HAS_INERT = 'inert' in D.documentElement;
  function focusables(container) {
    return $$(FOCUSABLE, container).filter(function (el) { return !el.hidden && el.getClientRects().length > 0; });
  }
  function trapFocus(container, e) {
    if (e.key !== 'Tab' || !container) return;
    var list = focusables(container);
    if (!list.length) { e.preventDefault(); return; }
    var first = list[0], last = list[list.length - 1], active = D.activeElement;
    if (!container.contains(active)) { e.preventDefault(); first.focus(); }
    else if (e.shiftKey && active === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && active === last) { e.preventDefault(); first.focus(); }
  }
  function lockBackground(keep, lock) {
    if (!frame) return;
    Array.prototype.slice.call(frame.children).forEach(function (el) {
      if (el.tagName === 'SCRIPT' || keep.indexOf(el) > -1) return;
      if (lock) {
        if (el.getAttribute('data-aa-bg')) return;
        el.setAttribute('data-aa-bg', '1');
        if (HAS_INERT) el.inert = true;
        if (!el.hasAttribute('aria-hidden')) { el.setAttribute('aria-hidden', 'true'); el.setAttribute('data-aa-bg', '2'); }
      } else if (el.getAttribute('data-aa-bg')) {
        if (HAS_INERT) el.inert = false;
        if (el.getAttribute('data-aa-bg') === '2') el.removeAttribute('aria-hidden');
        el.removeAttribute('data-aa-bg');
      }
    });
  }

  /* ---------- Mobile drawer ---------- */
  var drawer = $('#aaDrawer'), drawerBg = $('#aaDrawerBg'), menuBtn = $('#aaMenuBtn'), drawerClose = $('#aaDrawerClose');
  var drawerReturn = null;
  function drawerIsOpen() { return !!drawer && drawer.classList.contains('open'); }
  function openDrawer() {
    if (!drawer || drawerIsOpen()) return;
    drawerReturn = D.activeElement;
    drawer.classList.add('open');
    if (drawerBg) { drawerBg.classList.add('open'); drawerBg.hidden = false; drawerBg.setAttribute('aria-hidden', 'false'); }
    drawer.setAttribute('aria-hidden', 'false');
    lockBackground([drawer, drawerBg], true);
    if (menuBtn) { menuBtn.setAttribute('aria-expanded', 'true'); menuBtn.setAttribute('aria-label', 'Close menu'); }
    D.body.style.overflow = 'hidden';
    setTimeout(function () { if (drawerClose) drawerClose.focus(); }, 50);
  }
  function closeDrawer() {
    if (!drawerIsOpen()) return;
    drawer.classList.remove('open');
    if (drawerBg) { drawerBg.classList.remove('open'); drawerBg.hidden = true; drawerBg.setAttribute('aria-hidden', 'true'); }
    drawer.setAttribute('aria-hidden', 'true');
    lockBackground([], false);
    if (menuBtn) { menuBtn.setAttribute('aria-expanded', 'false'); menuBtn.setAttribute('aria-label', 'Open menu'); }
    D.body.style.overflow = '';
    var back = drawerReturn && D.contains(drawerReturn) ? drawerReturn : menuBtn;
    drawerReturn = null;
    if (back && back.focus) back.focus();
  }
  if (menuBtn) menuBtn.setAttribute('aria-expanded', 'false');
  on(menuBtn, 'click', function () { if (drawerIsOpen()) closeDrawer(); else openDrawer(); });
  on(drawerClose, 'click', closeDrawer);
  on(drawerBg, 'click', closeDrawer);

  /* ---------- Search overlay (modal dialog) ---------- */
  var searchOverlay = $('#aaSearchOverlay'), searchPanel = $('#aaSearchPanel'), searchBtn = $('#aaSearchBtn'), searchClose = $('#aaSearchClose');
  var form = $('#aaSearchForm'), typeSel = $('#aaSearchType'), input = $('#aaSearchInput'), sug = $('#aaSuggest'), timer = null, reqId = 0;
  var searchReturn = null;
  /* Section picker: a button that opens a list of every section (the hidden <select> keeps the value) */
  var typeBtn = $('#aaTypeBtn'), typeList = $('#aaTypeList'), typeLabelEl = $('#aaTypeLabel');
  function typeIsOpen() { return !!typeList && !typeList.hidden; }
  function setTypeList(open) {
    if (!typeList || !typeBtn) return;
    typeList.hidden = !open;
    typeBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
  if (typeSel && typeList && typeBtn) {
    typeList.innerHTML = Array.prototype.slice.call(typeSel.options).map(function (o) {
      return '<button type="button" class="type-opt" role="option" data-v="' + esc(o.value) + '" aria-selected="' + (o.value === typeSel.value ? 'true' : 'false') + '">' + esc(o.textContent) + '</button>';
    }).join('');
    on(typeBtn, 'click', function () { setTypeList(!typeIsOpen()); });
    on(typeList, 'click', function (e) {
      var b = e.target.closest ? e.target.closest('.type-opt') : null;
      if (!b) return;
      typeSel.value = b.getAttribute('data-v');
      if (typeLabelEl) typeLabelEl.textContent = b.textContent;
      $$('.type-opt', typeList).forEach(function (x) { x.setAttribute('aria-selected', x === b ? 'true' : 'false'); });
      setTypeList(false);
      if (input) { input.focus(); if (input.value.trim().length >= 2) runSuggest(); }
    });
  }
  function searchIsOpen() { return !!searchOverlay && searchOverlay.classList.contains('open'); }
  function openSearch() {
    if (!searchOverlay || searchIsOpen()) return;
    searchReturn = D.activeElement;
    searchOverlay.classList.add('open');
    searchOverlay.setAttribute('aria-hidden', 'false');
    lockBackground([searchOverlay], true);
    if (searchBtn) searchBtn.setAttribute('aria-expanded', 'true');
    D.body.style.overflow = 'hidden';
    setTimeout(function () { if (input) input.focus(); }, 80);
  }
  function closeSearch() {
    if (!searchIsOpen()) return;
    searchOverlay.classList.remove('open');
    searchOverlay.setAttribute('aria-hidden', 'true');
    lockBackground([], false);
    if (searchBtn) searchBtn.setAttribute('aria-expanded', 'false');
    D.body.style.overflow = '';
    if (sug) sug.innerHTML = '';
    setTypeList(false);
    reqId++; clearTimeout(timer);
    var back = searchReturn && D.contains(searchReturn) ? searchReturn : searchBtn;
    searchReturn = null;
    if (back && back.focus) back.focus();
  }
  function closeLbSafe() {
    var lb = $('#aaLightbox');
    if (lb && lb.classList.contains('open')) {
      lb.classList.remove('open');
      lb.setAttribute('aria-hidden', 'true');
      D.body.style.overflow = '';
      var li = $('#aaLightboxImg'); if (li) li.src = '';
    }
  }
  if (searchBtn) searchBtn.setAttribute('aria-expanded', 'false');
  on(searchBtn, 'click', openSearch);
  on(searchClose, 'click', closeSearch);
  on(searchOverlay, 'click', function (e) { if (e.target === searchOverlay) closeSearch(); });

  // One keyboard handler: Escape closes only the topmost layer; Tab is trapped inside an open modal.
  on(D, 'keydown', function (e) {
    if (e.key === 'Escape') {
      if (searchIsOpen()) { if (typeIsOpen()) { setTypeList(false); if (typeBtn) typeBtn.focus(); } else closeSearch(); }
      else if (drawerIsOpen()) closeDrawer();
      else closeLbSafe();
    } else if (e.key === 'Tab') {
      if (searchIsOpen()) trapFocus(searchPanel || searchOverlay, e);
      else if (drawerIsOpen()) trapFocus(drawer, e);
    }
  });

  on(form, 'submit', function () {
    form.action = typeSel && typeSel.value ? labelUrl(typeSel.value) : '/search';
  });
  function runSuggest() {
    clearTimeout(timer);
    var my = ++reqId;
    var q = input.value.trim();
    if (q.length < 2) { sug.innerHTML = ''; return; }
    sug.innerHTML = '<div class="search-loading">Searching…</div>';
    timer = setTimeout(function () {
      var base = typeSel && typeSel.value ? '/feeds/posts/summary/-/' + encodeURIComponent(typeSel.value) : '/feeds/posts/summary';
      getJSON(base + '?alt=json&max-results=8&q=' + encodeURIComponent(q), 1).then(function (j) {
        if (my !== reqId) return; // a newer query replaced this one
        var items = ((j.feed && j.feed.entry) || []).map(norm);
        if (!items.length) { sug.innerHTML = '<div class="search-empty">No results found</div>'; return; }
        sug.innerHTML = items.map(function (p) {
          var o = pick(p.labels);
          return '<a class="suggest-item" href="' + esc(p.url) + '">' +
            (p.thumb ? '<img loading="lazy" alt="" src="' + esc(p.thumb) + '"/>' : '<span class="art-ph"></span>') +
            '<span><span>' + esc(p.title) + '</span>' +
            (o.type ? '<div class="suggest-meta">' + esc(single(o.type)) + '</div>' : '') +
            '</span></a>';
        }).join('');
        bindImgFallback(sug);
      }).catch(function () { if (my === reqId) sug.innerHTML = '<div class="search-empty">Search unavailable</div>'; });
    }, 280);
  }
  on(input, 'input', runSuggest);
  on(typeSel, 'change', function () { if (input && input.value.trim().length >= 2) runSuggest(); });

  /* ---------- Feed helpers ---------- */
  function norm(e) {
    var url = '';
    (e.link || []).forEach(function (l) { if (l.rel === 'alternate') url = l.href; });
    var img = e['media$thumbnail'] ? e['media$thumbnail'].url : '';
    var raw = (e.summary && e.summary.$t) || (e.content && e.content.$t) || '';
    if (!img) { var m = /<img[^>]+src=["']([^"']+)["']/i.exec(raw); if (m) img = m[1]; }
    var re = /\/(s72-c|w72-h72[^\/]*)\//;
    return {
      title: (e.title && e.title.$t) || '', url: url,
      thumb: img ? img.replace(re, '/s96/') : '',
      poster: img ? img.replace(re, '/w400-h600-c/') : '',
      labels: (e.category || []).map(function (c) { return c.term; }),
      date: e.published ? e.published.$t : '',
      summary: raw.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 180)
    };
  }
  function fmtDate(iso) {
    if (!iso) return '';
    try { return new Date(iso).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }); }
    catch (e) { return ''; }
  }
  function bindImgFallback(root) {
    $$('img', root || D).forEach(function (img) {
      if (img.getAttribute('data-aa-fb')) return;
      img.setAttribute('data-aa-fb', '1');
      var onBroken = function () {
        img.style.display = 'none';
        var ph = img.nextElementSibling;
        if (ph && ph.classList && ph.classList.contains('art-ph')) ph.hidden = false;
        else if (img.parentNode) {
          var s = D.createElement('span'); s.className = 'art-ph'; s.setAttribute('aria-hidden', 'true');
          img.parentNode.insertBefore(s, img.nextSibling);
        }
      };
      on(img, 'error', onBroken);
      if (img.complete && img.naturalWidth === 0 && img.getAttribute('src')) onBroken(); // already failed before binding
    });
  }
  function posterHtml(p) {
    var o = pick(p.labels);
    return '<a class="poster-card" href="' + esc(p.url) + '"><div class="poster-art">' +
      (p.poster ? '<img loading="lazy" decoding="async" width="300" height="450" alt="' + esc(p.title) + '" src="' + esc(p.poster) + '"/>' +
        '<span class="art-ph" hidden="hidden" aria-hidden="true"></span>'
        : '<span class="art-ph" aria-hidden="true"></span>') +
      (o.type ? '<span class="poster-format-tag">' + esc(single(o.type)) + '</span>' : '') +
      (o.status ? '<div class="poster-overlay-bar"><span class="poster-episodes-tag">' + esc(pretty(o.status)) + '</span></div>' : '') +
      '</div><h3 class="poster-title">' + esc(p.title) + '</h3><div class="poster-meta-row"><span>' +
      esc(o.type ? single(o.type) : 'Article') + '</span><span>' + esc(fmtDate(p.date)) + '</span></div></a>';
  }
  function fetchLabels(labels, max) {
    var failed = false;
    return Promise.all(labels.map(function (l) {
      var url = (l ? '/feeds/posts/summary/-/' + encodeURIComponent(l) : '/feeds/posts/summary') + '?alt=json&max-results=' + max;
      return getJSON(url, 1).then(function (j) { return ((j.feed && j.feed.entry) || []).map(norm); })
        .catch(function () { failed = true; return []; });
    })).then(function (lists) {
      var seen = {}, all = [];
      lists.forEach(function (a) {
        a.forEach(function (p) { if (!seen[p.url]) { seen[p.url] = 1; all.push(p); } });
      });
      all.sort(function (a, b) { return a.date < b.date ? 1 : -1; });
      return { items: all.slice(0, max), failed: failed };
    });
  }

  /* ---------- Hero ---------- */
  var heroEl = $('#aaHero');
  if (heroEl) {
    fetchLabels(['FEATURED'], 5).then(function (r) {
      var items = r.items;
      if (!items.length) {
        return fetchLabels(['TRENDING'], 5).then(function (r2) { return r2.items; });
      }
      return items;
    }).then(function (items) {
      if (!items || !items.length) {
        heroEl.innerHTML = '';
        return;
      }
      var idx = 0;
      function render() {
        var p = items[idx];
        var o = pick(p.labels);
        heroEl.innerHTML =
          '<div class="hero-card">' +
            '<div class="hero-bg">' + (p.poster ? '<img alt="" src="' + esc(p.poster) + '"/>' : '') + '</div>' +
            '<div class="hero-overlay"></div>' +
            '<div class="hero-content">' +
              '<div class="hero-stamps">' +
                (o.type ? '<span class="stamp">' + esc(single(o.type)) + '</span>' : '') +
                (o.status ? '<span class="stamp status">' + esc(pretty(o.status)) + '</span>' : '') +
              '</div>' +
              '<h2 class="hero-title">' + esc(p.title) + '</h2>' +
              (p.summary ? '<p class="hero-desc">' + esc(p.summary) + '</p>' : '') +
              '<div class="hero-actions">' +
                '<a class="btn-primary" href="' + esc(p.url) + '">Read More</a>' +
                (o.type ? '<a class="btn-ghost" href="' + labelUrl(o.type) + '">Browse ' + esc(pretty(o.type)) + '</a>' : '') +
              '</div>' +
            '</div>' +
            (items.length > 1 ? '<div class="hero-nav" id="aaHeroNav">' +
              items.map(function (_, i) { return '<button type="button" class="hero-dot' + (i === idx ? ' on' : '') + '" data-i="' + i + '" aria-label="Slide ' + (i + 1) + '"></button>'; }).join('') +
            '</div>' : '') +
          '</div>';
        $$('.hero-dot', heroEl).forEach(function (dot) {
          on(dot, 'click', function () { idx = parseInt(dot.getAttribute('data-i'), 10); render(); });
        });
        bindImgFallback(heroEl);
      }
      render();
      var reduceMotion = W.matchMedia && W.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (items.length > 1 && !reduceMotion) {
        setInterval(function () { idx = (idx + 1) % items.length; render(); }, 7000);
      }
    }).catch(function () { if (heroEl) heroEl.innerHTML = ''; });
  }

  /* ---------- Homepage feed rows (lazy + prioritized) ---------- */
  var feedQueue = [];
  var feedActive = 0;
  var FEED_CONCURRENCY = 2;

  function runFeedQueue() {
    while (feedActive < FEED_CONCURRENCY && feedQueue.length) {
      var job = feedQueue.shift();
      feedActive++;
      job(function () { feedActive--; runFeedQueue(); });
    }
  }

  $$('[data-aa-feed]').forEach(function (box, boxIdx) {
    var block = box.closest('section');
    var labels = box.getAttribute('data-labels') === '' ? [''] : box.getAttribute('data-labels').split(',');
    var fb = box.getAttribute('data-fallback');
    var max = Math.min(parseInt(box.getAttribute('data-max'), 10) || 12, 12);
    var more = box.getAttribute('data-more');
    var loaded = false;

    function load(done) {
      if (loaded) { if (done) done(); return; }
      loaded = true;
      box.innerHTML = '<div class="skel"></div><div class="skel"></div><div class="skel"></div><div class="skel"></div>';
      if (block) block.hidden = false;
      var finished = false;
      function finish() { if (!finished) { finished = true; if (done) done(); } }
      function fail() {
        loaded = false;
        box.innerHTML = '<div class="feed-note" role="status">Could not load this section. <button type="button">Retry</button></div>';
        on($('button', box), 'click', function () {
          feedQueue.unshift(function (d) { load(d); });
          runFeedQueue();
        });
        finish();
      }
      fetchLabels(labels, max).then(function (r) {
        return (!r.items.length && !r.failed && fb) ? fetchLabels(fb.split(','), max) : r;
      }).then(function (r) {
        if (r.failed && !r.items.length) { fail(); return; }
        if (!r.items.length) { if (block) block.hidden = true; finish(); return; }
        box.innerHTML = r.items.map(posterHtml).join('') +
          (more ? '<a class="view-more-card" href="' + esc(more) + '"><span class="view-more-arrow">→</span><span>View More</span></a>' : '');
        $$('img', box).forEach(function (img) {
          img.setAttribute('decoding', 'async');
          if (!img.hasAttribute('loading')) img.setAttribute('loading', 'lazy');
        });
        bindImgFallback(box);
        finish();
      }).catch(fail);
    }

    // First two rails load immediately; rest wait until near viewport
    if (boxIdx < 2 || !('IntersectionObserver' in W)) {
      feedQueue.push(function (d) { load(d); });
      runFeedQueue();
    } else {
      box.innerHTML = '<div class="skel"></div><div class="skel"></div><div class="skel"></div><div class="skel"></div>';
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (en.isIntersecting) {
            io.disconnect();
            feedQueue.push(function (d) { load(d); });
            runFeedQueue();
          }
        });
      }, { rootMargin: '200px 0px' });
      io.observe(block || box);
    }
  });

  /* ---------- Genre browse ---------- */
  var gb = $('#aaGenres');
  if (gb) {
    gb.innerHTML = CFG.genres.map(function (g) {
      return '<a class="genre-nav-item" href="' + labelUrl('GENRE_' + g) + '">' + esc(pretty('GENRE_' + g)) + '</a>';
    }).join('');
  }

  /* ---------- Server-rendered poster cards ---------- */
  $$('#aaPosts .poster-card').forEach(function (c) {
    var ls = $$('.poster-labels-raw i', c).map(function (i) { return i.textContent.trim(); });
    var o = pick(ls);
    var tag = $('.poster-format-tag', c), bar = $('.poster-overlay-bar', c), pt = $('.poster-type', c);
    if (o.type) { tag.textContent = single(o.type); tag.hidden = false; }
    if (o.status) { $('.poster-episodes-tag', bar).textContent = pretty(o.status); bar.hidden = false; }
    if (pt) pt.textContent = o.type ? single(o.type) : 'Article';
  });
  bindImgFallback($('#aaPosts'));
  var grid = $('#aaPosts');
  if (grid && !$('.poster-card', grid)) {
    grid.outerHTML = '<div class="empty-state">No articles found here yet.</div>';
  }

  headDefaults();

  /* ---------- Label page header + chips ---------- */
  var lt = $('#aaLabelTitle');
  if (lt) {
    var label = lt.textContent.trim();
    lt.textContent = pretty(label);
    var sub = $('#aaLabelSub');
    if (sub) sub.textContent = CFG.subs[kind(label)] || 'All articles tagged ' + pretty(label) + '.';
    var ch = $('#aaChips');
    if (ch) {
      var rows = CFG.chips.slice();
      rows.push(CFG.genres.map(function (g) { return 'GENRE_' + g; }));
      ch.innerHTML = rows.map(function (row) {
        return '<div class="chip-row">' + row.map(function (l) {
          return '<a class="genre-nav-item' + (l === label ? ' on' : '') + '" href="' + labelUrl(l) + '">' + esc(pretty(l)) + '</a>';
        }).join('') + '</div>';
      }).join('');
    }
  }

  /* ---------- Article page ---------- */
  var post = $('#aaPost'), body = $('#aaBody');
  if (post && body) {
    var isPostKind = post.getAttribute('data-kind') === 'post';
    var title = ($('.ledger-title') || {}).textContent || D.title;

    $$('h1', body).forEach(function (h) {
      if (h.textContent.trim() === title.trim()) { h.remove(); }
      else {
        var h2 = D.createElement('h2');
        h2.innerHTML = h.innerHTML;
        h.parentNode.replaceChild(h2, h);
      }
    });

    var stamps = $('#aaStamps'), names = [], typeLabel = '', statusLabel = '', seriesLabel = '';
    var genreLabels = [];
    $$('#aaPostLabels a').forEach(function (a) {
      var n = a.textContent.trim(); names.push(n);
      var k = kind(n);
      if (k === 'SPECIAL') { a.remove(); return; }
      if (k === 'TYPE' || k === 'STATUS') {
        if (k === 'TYPE' && !typeLabel) typeLabel = n;
        if (k === 'STATUS' && !statusLabel) statusLabel = n;
        a.className = 'stamp' + (k === 'STATUS' ? ' status' : '');
        a.textContent = single(n);
        stamps.appendChild(a);
      } else if (k === 'SERIES') {
        if (!seriesLabel) seriesLabel = n;
        a.className = 'genre-chip';
        a.textContent = pretty(n);
      } else if (k === 'GENRE') {
        genreLabels.push(n);
        a.className = 'genre-chip';
        a.textContent = pretty(n);
      } else {
        // OTHER plain labels — show as chips, do not use as series id
        a.className = 'genre-chip';
        a.textContent = pretty(n);
      }
    });

    // Apply type class for CSS templates (posts only for encyclopedia chrome)
    if (typeLabel && isPostKind) post.setAttribute('data-type', typeLabel);
    var seriesTypes = ['TYPE_Anime','TYPE_Manga','TYPE_Manhwa','TYPE_Manhua','TYPE_Donghua','TYPE_Webtoon','TYPE_LightNovel','TYPE_WebNovel'];
    if (isPostKind && seriesTypes.indexOf(typeLabel) > -1) post.classList.add('is-series');

    var crumb = $('#aaCrumbType');
    if (crumb && typeLabel && isPostKind) {
      crumb.hidden = false;
      crumb.innerHTML = '<a href="' + labelUrl(typeLabel) + '">' + esc(pretty(typeLabel)) + '</a>';
    }

    var infoHost = $('.ledger-info');
    var titleEl = $('.ledger-title');

    // --- Specialized header blocks by type (skip on static pages) ---
    if (infoHost && typeLabel && isPostKind) {

      // Ranking / Guide badge
      if (typeLabel === 'TYPE_Ranking' || typeLabel === 'TYPE_Guide') {
        var badge = D.createElement('div');
        badge.className = 'aa-rank-badge';
        badge.textContent = typeLabel === 'TYPE_Ranking' ? '★ RANKING' : '✎ GUIDE';
        if (titleEl) infoHost.insertBefore(badge, titleEl);
        else infoHost.insertBefore(badge, infoHost.firstChild);
      }

      // Character: series link under title
      if (typeLabel === 'TYPE_Character' && seriesLabel && titleEl) {
        var alias = D.createElement('div');
        alias.className = 'aa-char-alias';
        alias.innerHTML = 'From <a href="' + labelUrl(seriesLabel) + '">' + esc(pretty(seriesLabel)) + '</a>';
        titleEl.parentNode.insertBefore(alias, titleEl.nextSibling);
      }

      // News byline
      if (typeLabel === 'TYPE_News') {
        var byline = D.createElement('div');
        byline.className = 'aa-news-byline';
        var dateSpan = ($('.ledger-meta span') || {}).textContent || '';
        byline.innerHTML =
          '<span class="news-cat">News</span>' +
          (dateSpan ? '<span>' + esc(dateSpan) + '</span>' : '') +
          (seriesLabel ? '<span>Topic: <a href="' + labelUrl(seriesLabel) + '">' + esc(pretty(seriesLabel)) + '</a></span>' : '');
        if (titleEl) titleEl.parentNode.insertBefore(byline, titleEl.nextSibling);
      }

      // Chapter / Volume / Arc context bar
      if (CFG.spoilerTypes.indexOf(typeLabel) > -1) {
        var ctx = D.createElement('div');
        ctx.className = 'aa-chapter-context';
        var ctxHtml = '';
        if (seriesLabel) {
          ctxHtml += '<a class="cc-series" href="' + labelUrl(seriesLabel) + '">' + esc(pretty(seriesLabel)) + '</a>';
          ctxHtml += '<span class="cc-sep">·</span>';
        }
        ctxHtml += '<span class="cc-meta">' + esc(pretty(typeLabel)) + '</span>';
        if (statusLabel) {
          ctxHtml += '<span class="cc-sep">·</span>';
          ctxHtml += '<span class="cc-meta">' + esc(pretty(statusLabel)) + '</span>';
        }
        ctx.innerHTML = ctxHtml;
        if (titleEl) infoHost.insertBefore(ctx, titleEl);
      }

      // Fact grid for series & characters
      if (seriesTypes.indexOf(typeLabel) > -1 || typeLabel === 'TYPE_Character') {
        var facts = [];
        if (typeLabel) facts.push({ k: 'Type', v: '<a href="' + labelUrl(typeLabel) + '">' + esc(pretty(typeLabel)) + '</a>' });
        if (statusLabel) facts.push({ k: 'Status', v: '<a href="' + labelUrl(statusLabel) + '">' + esc(pretty(statusLabel)) + '</a>' });
        if (seriesLabel && typeLabel === 'TYPE_Character') {
          facts.push({ k: 'Series', v: '<a href="' + labelUrl(seriesLabel) + '">' + esc(pretty(seriesLabel)) + '</a>' });
        }
        if (genreLabels.length) {
          facts.push({
            k: 'Genres',
            v: genreLabels.slice(0, 4).map(function (g) {
              return '<a href="' + labelUrl(g) + '">' + esc(pretty(g)) + '</a>';
            }).join(', ')
          });
        }
        if (facts.length) {
          var fg = D.createElement('div');
          fg.className = 'aa-fact-grid';
          fg.innerHTML = facts.map(function (f) {
            return '<div class="aa-fact"><span>' + esc(f.k) + '</span><strong>' + f.v + '</strong></div>';
          }).join('');
          infoHost.appendChild(fg);
        }
      }

      // Generic type bar for other types (news already has byline; chapters have context)
      var skipBar = ['TYPE_News', 'TYPE_Chapter', 'TYPE_Volume', 'TYPE_StoryArc'].indexOf(typeLabel) > -1
        || seriesTypes.indexOf(typeLabel) > -1 || typeLabel === 'TYPE_Character';
      if (!skipBar) {
        var barBits = [];
        if (typeLabel) barBits.push('<span><strong>Type</strong> <a href="' + labelUrl(typeLabel) + '">' + esc(pretty(typeLabel)) + '</a></span>');
        if (statusLabel) barBits.push('<span><strong>Status</strong> <a href="' + labelUrl(statusLabel) + '">' + esc(pretty(statusLabel)) + '</a></span>');
        if (seriesLabel) barBits.push('<span><strong>Series</strong> <a href="' + labelUrl(seriesLabel) + '">' + esc(pretty(seriesLabel)) + '</a></span>');
        if (genreLabels.length) {
          barBits.push('<span><strong>Genres</strong> ' + genreLabels.map(function (g) {
            return '<a href="' + labelUrl(g) + '">' + esc(pretty(g)) + '</a>';
          }).join(', ') + '</span>');
        }
        if (barBits.length) {
          var typeBar = D.createElement('div');
          typeBar.className = 'aa-type-bar';
          typeBar.innerHTML = barBits.join('');
          infoHost.appendChild(typeBar);
        }
      }
    }

    var art = $('#aaArt'), grid2 = $('#aaLedgerGrid');
    if (!art) { grid2.className += ' no-art'; }
    else {
      var artImg = $('img', art), key = (artImg.getAttribute('src') || '').split('/').pop().split('?')[0];
      var dropArt = function () { art.style.display = 'none'; if (grid2.className.indexOf('no-art') < 0) grid2.className += ' no-art'; };
      on(artImg, 'error', dropArt);
      if (artImg.complete && artImg.naturalWidth === 0) dropArt();
      var first = $('img', body);
      if (first && key && (first.getAttribute('src') || '').indexOf(key) > -1) {
        var holder = first.closest('.separator') || first.closest('figure') || first.parentNode;
        if (holder !== body && holder.textContent.trim() === '' && $$('img', holder).length === 1) holder.remove();
        else first.remove();
      }
    }

    var sp = $('#aaSpoiler');
    if (sp && CFG.spoilerTypes.some(function (t) { return names.indexOf(t) > -1; }) && !$('.aa-spoiler', body)) {
      sp.hidden = false;
    }

    $$('table', body).forEach(function (t) {
      var w = D.createElement('div'); w.className = 'aa-table-wrap';
      t.parentNode.insertBefore(w, t); w.appendChild(t);
    });
    $$('img', body).forEach(function (im, i) {
      if (i > 0 && !im.hasAttribute('loading')) im.setAttribute('loading', 'lazy');
      if (!im.alt) im.alt = title;
    });

    // Image lightbox
    var lb = $('#aaLightbox'), lbImg = $('#aaLightboxImg'), lbClose = $('#aaLightboxClose');
    function openLb(src, alt) {
      if (!lb) return;
      lbImg.src = src; lbImg.alt = alt || '';
      lb.classList.add('open'); lb.setAttribute('aria-hidden', 'false');
      D.body.style.overflow = 'hidden';
    }
    function closeLb() {
      if (!lb) return;
      lb.classList.remove('open'); lb.setAttribute('aria-hidden', 'true');
      D.body.style.overflow = ''; lbImg.src = '';
    }
    on(lbClose, 'click', closeLb);
    on(lb, 'click', function (e) { if (e.target === lb) closeLb(); });
    $$('img', body).forEach(function (im) {
      on(im, 'click', function () { openLb(im.src, im.alt); });
    });

    var words = (body.textContent || '').trim().split(/\s+/).length;
    var rt = $('#aaReadTime');
    if (rt) rt.textContent = Math.max(1, Math.round(words / 220)) + ' min read';

    var heads = $$('h2, h3', body).filter(function (h) { return !h.closest('.aa-toc'); });
    heads.forEach(function (h, i) { if (!h.id) h.id = 'sec-' + (i + 1); });
    function tocList() {
      return '<ol>' + heads.map(function (h) {
        return '<li class="' + (h.tagName === 'H3' ? 'l3' : 'l2') + '"><a href="#' + h.id + '">' + esc(h.textContent.trim()) + '</a></li>';
      }).join('') + '</ol>';
    }
    if (isPostKind && heads.length >= 3) {
      var toc = $('.aa-toc', body);
      if (toc && !$('a', toc)) { toc.innerHTML = '<h3>CONTENTS</h3>' + tocList(); }
      else if (!toc) {
        var d = D.createElement('details'); d.className = 'aa-toc'; d.open = true;
        d.innerHTML = '<summary>CONTENTS</summary>' + tocList();
        heads[0].parentNode.insertBefore(d, heads[0]);
      }
    }

    var bar = $('#aaProgress');
    function prog() {
      if (!bar || !body) return;
      var r = body.getBoundingClientRect(), total = r.height - W.innerHeight * 0.5;
      var p = total > 0 ? Math.min(1, Math.max(0, (-r.top + W.innerHeight * 0.2) / total)) : 0;
      bar.style.width = (p * 100).toFixed(1) + '%';
    }
    if (isPostKind) { on(W, 'scroll', prog); on(W, 'resize', prog); prog(); }

    var sh = $('#aaShare');
    if (sh) {
      var u = encodeURIComponent(W.location.href.split('#')[0]), t = encodeURIComponent(title);
      sh.insertAdjacentHTML('beforeend',
        '<a target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u=' + u + '">Facebook</a>' +
        '<a target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?url=' + u + '&text=' + t + '">X</a>' +
        '<a target="_blank" rel="noopener" href="https://wa.me/?text=' + t + '%20' + u + '">WhatsApp</a>' +
        '<a target="_blank" rel="noopener" href="https://t.me/share/url?url=' + u + '&text=' + t + '">Telegram</a>' +
        '<button type="button" id="aaCopy">Copy link</button>');
      on($('#aaCopy'), 'click', function () {
        var b = this;
        if (navigator.clipboard) {
          navigator.clipboard.writeText(W.location.href.split('#')[0]).then(function () {
            b.textContent = 'Copied';
            setTimeout(function () { b.textContent = 'Copy link'; }, 2000);
          });
        }
      });
    }

    // ---------- Phase 5: Series relationships & chapter navigation ----------
    var rel = $('#aaRelated');
    var isChapterLike = CFG.spoilerTypes.indexOf(typeLabel) > -1;
    var isSeriesPage = seriesTypes.indexOf(typeLabel) > -1;
    var curPath = W.location.pathname;

    function chapterNum(title) {
      // Extract chapter/episode/volume numbers for ordering
      var m = (title || '').match(/(?:ch(?:apter)?|ep(?:isode)?|vol(?:ume)?|arc)\s*[.#]?\s*(\d+(?:\.\d+)?)/i)
        || (title || '').match(/#\s*(\d+(?:\.\d+)?)/)
        || (title || '').match(/\b(\d+(?:\.\d+)?)\s*$/);
      return m ? parseFloat(m[1]) : null;
    }
    function sortByChapter(a, b) {
      var na = chapterNum(a.title), nb = chapterNum(b.title);
      if (na != null && nb != null) return na - nb;
      if (na != null) return -1;
      if (nb != null) return 1;
      return (a.date < b.date ? -1 : 1);
    }
    function fillRelated(items, heading) {
      if (!rel || !items.length) return;
      var titleEl = $('.section-title', rel);
      var subEl = $('#aaRelatedSub');
      if (titleEl && heading) titleEl.textContent = heading;
      if (subEl) subEl.textContent = items.length + ' related article' + (items.length === 1 ? '' : 's');
      $('#aaRelatedGrid').innerHTML = items.map(posterHtml).join('');
      bindImgFallback($('#aaRelatedGrid'));
      rel.hidden = false;
    }
    function hasType(p, t) {
      return (p.labels || []).indexOf(t) > -1;
    }
    function hasAnyType(p, types) {
      return (p.labels || []).some(function (l) { return types.indexOf(l) > -1; });
    }

    // Build series-aware navigation and related content (posts only; skip static pages)
    if (seriesLabel && isPostKind) {
      // One COMPLETE series fetch: every page until the feed is exhausted (parallel, cached for the session).
      // Chapters, volumes, arcs, characters and related posts are all partitioned from it by label.
      var seriesPath = '/feeds/posts/summary/-/' + encodeURIComponent(seriesLabel);

      fetchAllPosts(seriesPath).then(function (res) {
        var byUrl = {};
        res.items.forEach(function (p) { if (p.url) byUrl[p.url] = p; });
        var all = Object.keys(byUrl).map(function (k) { return byUrl[k]; });
        var others = all.filter(function (p) { return p.url.indexOf(curPath) < 0; });

        // Strict type partitions — never mix chapter/volume/arc for navigation
        var onlyChapters = all.filter(function (p) { return hasType(p, 'TYPE_Chapter'); }).sort(sortByChapter);
        var onlyVolumes = all.filter(function (p) { return hasType(p, 'TYPE_Volume'); }).sort(sortByChapter);
        var onlyArcs = all.filter(function (p) { return hasType(p, 'TYPE_StoryArc'); }).sort(sortByChapter);
        var characters = others.filter(function (p) { return hasType(p, 'TYPE_Character'); });
        var seriesPosts = others.filter(function (p) { return hasAnyType(p, seriesTypes); });

        // Nav list is same type only
        var navList = [];
        var navLabel = 'ITEMS';
        if (typeLabel === 'TYPE_Chapter') { navList = onlyChapters; navLabel = 'CHAPTERS'; }
        else if (typeLabel === 'TYPE_Volume') { navList = onlyVolumes; navLabel = 'VOLUMES'; }
        else if (typeLabel === 'TYPE_StoryArc') { navList = onlyArcs; navLabel = 'STORY ARCS'; }

        // --- Same-type prev/next navigation ---
        if (isChapterLike && navList.length > 1) {
          var curIdx = -1;
          navList.forEach(function (p, i) {
            if (p.url.indexOf(curPath) > -1 || (p.title && title && p.title.trim() === title.trim())) curIdx = i;
          });
          if (curIdx < 0) {
            navList.forEach(function (p, i) {
              try {
                if (new URL(p.url).pathname === curPath) curIdx = i;
              } catch (e) {}
            });
          }

          if (curIdx >= 0) {
            var prevCh = curIdx > 0 ? navList[curIdx - 1] : null;
            var nextCh = curIdx < navList.length - 1 ? navList[curIdx + 1] : null;
            var postNav = $('.post-nav');
            if (postNav && (prevCh || nextCh)) {
              var navHtml = '';
              if (prevCh) {
                navHtml += '<a class="prev" href="' + esc(prevCh.url) + '" rel="prev">' +
                  '<small>← PREVIOUS ' + esc(pretty(typeLabel).toUpperCase()) + '</small>' +
                  esc(prevCh.title.length > 48 ? prevCh.title.slice(0, 46) + '…' : prevCh.title) + '</a>';
              } else {
                navHtml += '<span></span>';
              }
              if (nextCh) {
                navHtml += '<a class="next" href="' + esc(nextCh.url) + '" rel="next">' +
                  '<small>NEXT ' + esc(pretty(typeLabel).toUpperCase()) + ' →</small>' +
                  esc(nextCh.title.length > 48 ? nextCh.title.slice(0, 46) + '…' : nextCh.title) + '</a>';
              }
              postNav.innerHTML = navHtml;
              postNav.setAttribute('aria-label', 'Series ' + pretty(typeLabel).toLowerCase() + ' navigation');
            }
          }

          // Strip centered on current item (±8 neighbors)
          var nav = D.createElement('div');
          nav.className = 'aa-series-nav';
          var windowSize = 16;
          var list;
          if (curIdx >= 0 && navList.length > windowSize) {
            var start = Math.max(0, curIdx - Math.floor(windowSize / 2));
            var end = Math.min(navList.length, start + windowSize);
            start = Math.max(0, end - windowSize);
            list = navList.slice(start, end);
          } else {
            list = navList.slice(0, windowSize);
          }
          nav.innerHTML = '<div class="sn-label">' + navLabel + ' IN ' + esc(pretty(seriesLabel).toUpperCase()) +
            (navList.length > windowSize ? ' · ' + navList.length + ' total' : '') + '</div>' +
            list.map(function (p) {
              var isCur = p.url.indexOf(curPath) > -1 || (p.title && title && p.title.trim() === title.trim());
              return '<a href="' + esc(p.url) + '"' + (isCur ? ' class="current"' : '') + '>' +
                esc(p.title.length > 40 ? p.title.slice(0, 38) + '…' : p.title) + '</a>';
            }).join('');
          var bodyParent = body.parentNode;
          if (bodyParent) bodyParent.insertBefore(nav, body.nextSibling);
        }

        // Aliases used by hub / related code below
        var chapters = onlyChapters;
        var volumes = onlyVolumes;
        var arcs = onlyArcs;

        // --- Series page: "In this series" hub ---
        if (isSeriesPage && others.length) {
          var hub = D.createElement('div');
          hub.className = 'aa-series-nav';
          var hubHtml = '<div class="sn-label">IN THIS SERIES</div>';
          var hubLinks = [];
          if (chapters.filter(function (p) { return p.url.indexOf(curPath) < 0; }).length) {
            hubLinks.push('<a href="' + labelUrl(seriesLabel) + '">All series posts</a>');
          }
          if (characters.length) {
            hubLinks.push('<a href="/search/label/' + encodeURIComponent('TYPE_Character') + '?q=' + encodeURIComponent(pretty(seriesLabel)) + '">Characters (' + characters.length + ')</a>');
          }
          if (volumes.length) {
            hubLinks.push('<a href="/search/label/' + encodeURIComponent('TYPE_Volume') + '">Volumes (' + volumes.length + ')</a>');
          }
          if (arcs.length) {
            hubLinks.push('<a href="/search/label/' + encodeURIComponent('TYPE_StoryArc') + '">Story Arcs (' + arcs.length + ')</a>');
          }
          var chapterOnly = chapters.filter(function (p) { return hasType(p, 'TYPE_Chapter') && p.url.indexOf(curPath) < 0; });
          if (chapterOnly.length) {
            hubLinks.push('<a href="/search/label/' + encodeURIComponent('TYPE_Chapter') + '">Chapters (' + chapterOnly.length + ')</a>');
          }
          if (hubLinks.length) {
            hub.innerHTML = hubHtml + hubLinks.join('');
            var bodyParent2 = body.parentNode;
            if (bodyParent2) bodyParent2.insertBefore(hub, body.nextSibling);
          }
        }

        // --- Character page: link back to series + sibling characters ---
        if (typeLabel === 'TYPE_Character' && characters.length) {
          var charNav = D.createElement('div');
          charNav.className = 'aa-series-nav';
          charNav.innerHTML = '<div class="sn-label">CHARACTERS IN ' + esc(pretty(seriesLabel).toUpperCase()) + '</div>' +
            characters.slice(0, 12).map(function (p) {
              return '<a href="' + esc(p.url) + '">' + esc(p.title.length > 36 ? p.title.slice(0, 34) + '…' : p.title) + '</a>';
            }).join('');
          var bp = body.parentNode;
          if (bp) bp.insertBefore(charNav, body.nextSibling);
        }

        // Related grid priority: same series, prefer complementary types
        var chapterOnlyAll = chapters.filter(function (p) {
          return hasType(p, 'TYPE_Chapter') && p.url.indexOf(curPath) < 0;
        });
        var relatedPool = others.slice();
        if (isSeriesPage) {
          relatedPool = characters.concat(chapterOnlyAll).concat(others);
        } else if (typeLabel === 'TYPE_Character') {
          relatedPool = characters.concat(seriesPosts).concat(others);
        } else if (isChapterLike) {
          relatedPool = chapterOnlyAll.concat(characters).concat(others);
        }
        var seenRel = {};
        relatedPool = relatedPool.filter(function (p) {
          if (seenRel[p.url]) return false;
          seenRel[p.url] = 1;
          return true;
        });
        var relatedItems = relatedPool.slice(0, CFG.related);
        if (relatedItems.length) {
          fillRelated(relatedItems, 'More from ' + pretty(seriesLabel));
        } else if (typeLabel) {
          return getJSON('/feeds/posts/summary/-/' + encodeURIComponent(typeLabel) + '?alt=json&max-results=' + (CFG.related + 2))
            .then(function (j2) {
              var items = ((j2.feed && j2.feed.entry) || []).map(norm)
                .filter(function (p) { return p.url.indexOf(curPath) < 0; }).slice(0, CFG.related);
              fillRelated(items, 'Related');
            });
        }
      }).catch(function () {});
    } else if (rel && typeLabel && !$('.aa-related a', body)) {
      getJSON('/feeds/posts/summary/-/' + encodeURIComponent(typeLabel) + '?alt=json&max-results=' + (CFG.related + 2)).then(function (j) {
        var items = ((j.feed && j.feed.entry) || []).map(norm)
          .filter(function (p) { return p.url.indexOf(curPath) < 0; }).slice(0, CFG.related);
        fillRelated(items, 'Related');
      }).catch(function () {});
    }

    // ---------- Phase 6: SEO meta + richer structured data ----------
    // (setMeta / fill / ensureCanonical / dedupeHead are defined once at the top of the script)

    // Build description from body if missing
    var bodyText = (body.textContent || '').replace(/\s+/g, ' ').trim();
    var autoDesc = bodyText.slice(0, 160).replace(/\s+\S*$/, '') + (bodyText.length > 160 ? '…' : '');

    if (isPostKind) {
      var canon = ensureCanonical(W.location.href.split('?')[0].split('#')[0]);
      var ogImg = ($('meta[property="og:image"]') || {}).content || '';
      var artImg = ($('#aaArt img') || {}).src || '';
      if (!ogImg && artImg) ogImg = artImg;

      var desc = ($('meta[name=description]') || {}).content || '';
      if (!desc && autoDesc) {
        desc = autoDesc;
        setMeta('name', 'description', desc);
        setMeta('property', 'og:description', desc);
        setMeta('name', 'twitter:description', desc);
      }

      // Ensure core OG/Twitter tags exist (only fills gaps; never duplicates or overrides Blogger's)
      fill('property', 'og:title', title.slice(0, 110));
      fill('name', 'twitter:title', title.slice(0, 110));
      fill('property', 'og:url', canon);
      fill('name', 'twitter:url', canon);
      fill('property', 'og:type', 'article');
      fill('property', 'og:site_name', 'ANIME ARCHIVE');
      fill('name', 'twitter:card', 'summary_large_image');
      if (ogImg) {
        fill('property', 'og:image', ogImg);
        fill('name', 'twitter:image', ogImg);
      }

      // Article-specific OG
      setMeta('property', 'article:section', typeLabel ? pretty(typeLabel) : 'Encyclopedia');
      if (genreLabels.length) {
        genreLabels.forEach(function (g) {
          var t = D.createElement('meta');
          t.setAttribute('property', 'article:tag');
          t.setAttribute('content', pretty(g));
          D.head.appendChild(t);
        });
      }

      // JSON-LD
      var schemaType = 'Article';
      if (names.indexOf('TYPE_News') > -1) schemaType = 'NewsArticle';
      var art2 = {
        '@context': 'https://schema.org',
        '@type': schemaType,
        headline: title.slice(0, 110),
        mainEntityOfPage: { '@type': 'WebPage', '@id': canon },
        url: canon,
        isAccessibleForFree: true,
        publisher: {
          '@type': 'Organization',
          name: 'ANIME ARCHIVE',
          url: ORIGIN + '/',
          logo: { '@type': 'ImageObject', url: ORIGIN + '/favicon.ico' }
        }
      };
      if (desc) art2.description = desc;
      if (ogImg) art2.image = [ogImg];
      if (genreLabels.length) art2.keywords = genreLabels.map(pretty).concat(typeLabel ? [pretty(typeLabel)] : []).join(', ');
      if (seriesLabel) art2.about = { '@type': 'Thing', name: pretty(seriesLabel) };

      var crumbs = [{ '@type': 'ListItem', position: 1, name: 'Home', item: ORIGIN + '/' }];
      if (typeLabel) crumbs.push({ '@type': 'ListItem', position: 2, name: pretty(typeLabel), item: ORIGIN + labelUrl(typeLabel) });
      if (seriesLabel) crumbs.push({ '@type': 'ListItem', position: crumbs.length + 1, name: pretty(seriesLabel), item: ORIGIN + labelUrl(seriesLabel) });
      crumbs.push({ '@type': 'ListItem', position: crumbs.length + 1, name: title });

      var emit = function (o) {
        var s = D.createElement('script'); s.type = 'application/ld+json'; s.text = JSON.stringify(o); D.head.appendChild(s);
      };
      var pid = post.getAttribute('data-post-id');
      var done = function () {
        emit(art2);
        emit({ '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: crumbs });
      };
      if (pid) {
        getJSON('/feeds/posts/default/' + encodeURIComponent(pid) + '?alt=json').then(function (j) {
          var e = j.entry || {};
          if (e.published) {
            art2.datePublished = e.published.$t;
            setMeta('property', 'article:published_time', e.published.$t);
          }
          if (e.updated) {
            art2.dateModified = e.updated.$t;
            setMeta('property', 'article:modified_time', e.updated.$t);
          }
          if (e.author && e.author[0] && e.author[0].name) {
            art2.author = { '@type': 'Person', name: e.author[0].name.$t };
          } else {
            art2.author = { '@type': 'Organization', name: 'ANIME ARCHIVE' };
          }
          done();
        }).catch(function () {
          art2.author = { '@type': 'Organization', name: 'ANIME ARCHIVE' };
          done();
        });
      } else {
        art2.author = { '@type': 'Organization', name: 'ANIME ARCHIVE' };
        done();
      }
    } else if (!isPostKind && post) {
      // Static pages
      var pageCanon = ensureCanonical(W.location.href.split('?')[0].split('#')[0]);
      if (autoDesc) {
        fill('name', 'description', autoDesc);
        fill('property', 'og:description', autoDesc);
      }
      fill('property', 'og:title', title);
      fill('property', 'og:url', pageCanon);
      fill('property', 'og:type', 'website');
    }
  }

  /* ---------- Back to top ---------- */
  var topBtn = $('#aaTop');
  if (topBtn) {
    on(W, 'scroll', function () {
      if (W.scrollY > 500) topBtn.classList.add('show');
      else topBtn.classList.remove('show');
    });
    on(topBtn, 'click', function () { W.scrollTo({ top: 0, behavior: 'smooth' }); });
  }

  /* ---------- Homepage + listing structured data ---------- */
  if ($('#aaHome')) {
    var ld = D.createElement('script'); ld.type = 'application/ld+json';
    ld.text = JSON.stringify([
      {
        '@context': 'https://schema.org', '@type': 'WebSite',
        name: 'ANIME ARCHIVE',
        url: ORIGIN + '/',
        description: 'Anime, manga, manhwa and manhua encyclopedia',
        potentialAction: {
          '@type': 'SearchAction',
          target: { '@type': 'EntryPoint', urlTemplate: ORIGIN + '/search?q={search_term_string}' },
          'query-input': 'required name=search_term_string'
        }
      },
      {
        '@context': 'https://schema.org', '@type': 'Organization',
        name: 'ANIME ARCHIVE',
        url: ORIGIN + '/',
        sameAs: []
      }
    ]);
    D.head.appendChild(ld);
  }

  // Label / search listing pages
  var labelTitle = $('#aaLabelTitle');
  if (labelTitle && !$('#aaHome')) {
    var listName = labelTitle.textContent.trim();
    var listUrl = W.location.href.split('?')[0].split('#')[0];
    var items = $$('#aaPosts .poster-card').slice(0, 20).map(function (card, i) {
      return {
        '@type': 'ListItem',
        position: i + 1,
        url: card.href,
        name: (($('.poster-title', card) || {}).textContent || '').trim()
      };
    }).filter(function (x) { return x.name; });
    var col = {
      '@context': 'https://schema.org',
      '@type': 'CollectionPage',
      name: listName + ' — ANIME ARCHIVE',
      url: listUrl,
      isPartOf: { '@type': 'WebSite', name: 'ANIME ARCHIVE', url: ORIGIN + '/' }
    };
    if (items.length) {
      col.mainEntity = {
        '@type': 'ItemList',
        itemListElement: items,
        numberOfItems: items.length
      };
    }
    var sCol = D.createElement('script'); sCol.type = 'application/ld+json';
    sCol.text = JSON.stringify(col);
    D.head.appendChild(sCol);

    // Breadcrumb for label pages
    var lCrumbs = {
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'Home', item: ORIGIN + '/' },
        { '@type': 'ListItem', position: 2, name: listName }
      ]
    };
    var sCr = D.createElement('script'); sCr.type = 'application/ld+json';
    sCr.text = JSON.stringify(lCrumbs);
    D.head.appendChild(sCr);
  }

  dedupeHead();
})();
//
